  "Утга засах": "Edit value",
  "Ухаалаг хот": "Smart City",
  "3. ОЛОН зүйлийг харьцуулбал энгийн хүснэгт (нэг мөр = нэг зүйл).": "3. When comparing MANY items, use a plain table (one row = one item).",
  "3. Хариулт бүрд ЭХ СУРВАЛЖИЙГ заавал бич: id ба талбарын нэр (жиш. «эх сурвалж: `et:24` / `population`»).": "3. Always cite the SOURCE in every answer: the id and field name (e.g. “source: `et:24` / `population`”).",
  "3D бодит загвар ачаалагдсангүй (": "The 3D reality model could not be loaded (",
  "4 ээлж": "4 phases",
  "4. Асуултад тохирох өгөгдөл БАЙХГҮЙ бол ГУРВАН зүйлийг энэ дарааллаар хэл:": "4. If there is NO data for the question, say THREE things in this order:",
  "4. Газар чөлөөлөлт": "4. Land acquisition",
  "4. Дараа нь ДЭЛГЭРЭНГҮЙГ **бүлэглэсэн жагсаалтаар**. Бүлэг бүр тод гарчигтай:": "4. Then the DETAIL as a **grouped list**. Each group has a bold heading:",
  "5. ДЭЛГЭРЭНГҮЙ бич: татсан өгөгдлөөс хэрэглэгчид ХЭРЭГТЭЙ бүхнийг оруул —": "5. Be THOROUGH: include everything from the retrieved data that is USEFUL to the user —",
  "5. Нийгмийн үйлчилгээний барилга": "5. Social service buildings",
  "5. Хоёр талбар аль нь ч тохирч магадгүй бол ТААМАГЛАХГҮЙ — хэрэглэгчээс аль нь болохыг богинохон асуу.": "5. If two fields could both fit, do NOT guess — ask the user briefly which one is meant.",
  "6 м²/хүн": "6 m²/person",
  "6. Барилга угсралтын гүйцэтгэл": "6. Construction progress",
  "6. Догол мөр 2 мөрөөс урт байж БОЛОХГҮЙ. Урт бичвэр = жагсаалт болгоно.": "6. A paragraph must NOT exceed 2 lines. Longer text becomes a list.",
  "7. Гарчиг (`#`) хэрэглэхгүй — бүлгийн нэрийг `**тодоор**` бич.": "7. Do not use headings (`#`) — write group names in `**bold**`.",
  "7. Санхүүжилтийн явц": "7. Funding progress",
  "8 ээлж": "8 phases",
  "8. Дэд бүтцийн хэрэгжилт": "8. Infrastructure delivery",
  "8. Санхүү (мөнгөн урсгал, хөрөнгө оруулалт) ба төслийн явцын өгөгдөл ЭНЭ ХЭРЭГЛЭГЧИД хаалттай. Асуувал «энэ мэдээлэл агентад хараахан нээгдээгүй байна» гэж хэл.": "8. Finance (cash flow, investment) and project progress data are CLOSED to THIS USER. If asked, say “this data has not yet been made available to the assistant”.",
  "8. ХАМГИЙН СҮҮЛД дан мөрөнд: `Эх сурвалж: \\`давхарга\\` / \\`талбар\\`` — өөр юу ч нэмэхгүй.": "8. LAST, on its own line: `Source: \\`layer\\` / \\`field\\`` — add nothing else.",
