  "Чирж өөрчилсөн бүх баганы өргөнийг анхны хэмжээнд нь буцаана": "Resets every dragged column width to its original size",
  "Өргөн сэргээх": "Reset widths",
  "№ ба Ажлын нэр нь excel-ийн бүтэц — энэ хуудаснаас засагдахгүй.": "№ and the task name come from the excel structure — not editable on this page.",
  "Хувийн жин: Мөнгөн дүн ÷ дээд мөрийн дүн. Автоматаар бодогдоно.": "Weight: amount ÷ the parent row's amount. Computed automatically.",
  "Хувийн жин (нийт төсөлд): Мөнгөн дүн ÷ үе шатны дүн. Автоматаар бодогдоно.": "Weight (of the whole project): amount ÷ the phase amount. Computed automatically.",
  "Одоо байгаа: Хувийн жин × Бодит гүйцэтгэл. Гүйцэтгэл бөглөхөд өөрөө хөдөлнө.": "Current: weight × actual progress. Moves on its own as progress is filled in.",
  "Обьём нь ЭХ ӨГӨГДЛИЙН тоо хэмжээ — эх хүснэгтэд оруулагдана, энэ хуудаснаас засагдахгүй (жин, мөнгөн дүн бүхэлдээ түүнээс бодогддог).": "Volume is the SOURCE quantity — it is entered in the source table and not editable here (all weights and amounts are derived from it).",
  "Нэгж өртөг нь үйлчилгээнд хадгалагдсан — энэ хуудаснаас засагдахгүй.": "Unit cost is stored in the service — not editable on this page.",
  "Мөнгөн дүн: Обьём × Нэгж өртөг; бүлгийн мөрд дэд мөрүүдийнхээ нийлбэр.": "Amount: volume × unit cost; on group rows, the sum of their child rows.",
  "Төлөвлөгөөт гүйцэтгэл нь блокуудын төлөвлөгөөт хувийн дундаж. Огноог засвал өөрчлөгдөнө.": "Planned progress is the mean of the blocks' planned percents. It changes when the date is edited.",
  "Бодит гүйцэтгэл нь блокуудын бодит хувийн дундаж. Блокийн нүдэнд обьём бөглөнө үү.": "Actual progress is the mean of the blocks' actual percents. Enter volumes into the block cells.",
  "Төлөвлөгөө биелэлт: Бодит ÷ Төлөвлөгөөт. Автоматаар бодогдоно.": "Plan attainment: actual ÷ planned. Computed automatically.",
  "Бүлгийн мөр нь дэд мөрүүдийнхээ жинтэй дунджаар бодогдоно — доод ажлын мөр дээр бөглөнө үү.": "Group rows are the weighted mean of their child rows — fill in on the task rows below.",
  "Энэ мөрд «Обьём» бөглөгдөөгүй тул хувь бодогдохгүй. Обьёмын баганад мөрийн нийт тоо хэмжээг оруулмагц хувь нь өөрөө гарч эхэлнэ.": "This row has no “volume” yet, so no percent can be computed. Once the row's total quantity is entered in the volume column, the percent appears automatically.",
  "Барилга-төлөвлөгөөт нь эхлэх/дуусах огноо ба шинэчлэгдсэн огноогоор бодогдоно — огноог нь засаарай.": "The per-building plan is computed from the start/finish dates and the as-of date — edit those dates.",
  "Энэ огноо нь доод ажлуудынхаа хамгийн эрт эхлэх / хамгийн сүүл дуусахаар бодогдож байна — доод ажлынхаа огноог засаарай.": "This date is the earliest start / latest finish of the tasks below — edit those tasks' dates.",
  "Энэ блокт огнооны багана үйлчилгээнд байхгүй тул хадгалах газаргүй.": "This block has no date column in the service, so there is nowhere to save.",
  "Шинэчлэгдсэн огноо зөвхөн эхний мөрд бичигдэнэ — тэндээс эсвэл дээд талын «Огноо»-гоор солино.": "The as-of date is written only on the first row — change it there or with the Date control above.",
