  "№": "No.",
  "Энэ хэрэглэгч урсгалын шатанд томилогдсон. «Гүйцэтгэлийн хяналт»-ыг унтраавал ажлаа хянаж чадахгүй болно. Унтраах уу?": "This user is assigned to a workflow stage. Turning off “Execution review” will leave them unable to review their work. Turn it off?",
  "«{0}» нь ArcGIS хэрэглэгчийн нэрийн бүтцэд тохирохгүй (латин үсэг/тоо, 3+ тэмдэгт).": "“{0}” does not look like a valid ArcGIS username (Latin letters/digits, 3+ characters).",
  "Урсгалын томилгоог «Гүйцэтгэлийн урсгалын эрх» хуудсанд засна — дарж очно": "Workflow assignments are edited on the “Execution workflow permissions” page — click to go there",
  "порталд алга": "not in portal",
  "Enterprise порталд энэ нэртэй аккаунт алга — нэвтэрч чадахгүй. Хуваарилалтыг нь өөр хүнд шилжүүлэх, эсвэл устгана уу.": "No account with this name exists in the Enterprise portal — it cannot sign in. Reassign its assignments to someone else, or delete it.",
  "«{0}» төрөлтэй атлаа «{1}» шатанд томилогдсон — шат нь томилгооноос. Дарж «Гүйцэтгэлийн урсгалын эрх» руу очно.": "Type “{0}” but assigned to the “{1}” stage — the stage comes from the assignment. Click to open “Execution workflow permissions”.",
  "«{0}» төрөл урсгалын шат олгодоггүй — «Гүйцэтгэлийн урсгалын эрх» хуудсанд «{0}» шатанд томилохгүй бол «Гүйцэтгэл» хуудас нээгдэхгүй, батлахгүй. Дарж очно.": "The “{0}” type does not grant a workflow stage — unless assigned to the “{0}” stage on “Execution workflow permissions”, the “Execution” page stays closed and nothing can be approved. Click to go there.",
  "⚠ төрөл ≠ шат": "⚠ type ≠ stage",
  "⚠ шатгүй": "⚠ no stage",
  "Бүх харагдац ба админ портал нээгдэнэ — super эрх нь эрхийн тохиргооноос (өөр super админ олгоно/хасна).": "Opens every view and the admin portal — super rights come from the permission settings (another super admin grants/removes them).",
