  "«{0}»-г {1} шатнаас хасах уу? Олгогдсон үүрэг ба «Гүйцэтгэлийн хяналт» харагдац нь мөн буцаагдана.": "Remove “{0}” from the {1} stage? The granted role and the “Execution review” view will also be revoked.",
