  "Өртөлтөөр: ЗӨВХӨН барилгаас — барилгын хүн ам (оршин суугч + хүчин чадал) × мужид орсон хувь; хүн амгүй барилгад шалны {0} м²-д 1 хүн. Хүн тутамд өдрийн {1} ₮ зардлын таамгаар. Эмнэлгийн бодит бүртгэлээс уншаагүй.": "By exposure, from BUILDINGS only — building population (residents + capacity) × share inside the zone; buildings without population count 1 person per {0} m² of floor area. At an assumed {1} ₮ per person per day. Not read from actual medical records.",
