  "Багц тус бүрд Зохиогч ба Батлагч аккаунтыг тусад нь томилно. Нэг багцад хэдэн ч аккаунт байж болно.": "Assign Drafter and Approver accounts separately for each package. A package can have any number of accounts.",
  "Зохиогч томилоогүй": "No drafter assigned",
  "Батлагч томилоогүй": "No approver assigned",
  "устгагдсан аккаунт": "deleted account",
  "Энэ багцаас хасах": "Remove from this package",
  "Аккаунт нэмэх…": "Add an account…",
  "Чөлөөтэй аккаунт алга": "No accounts available",
  "⚠️ Батлагч нь зохиогчтой ижил хүн — өөрийн илгээснийг өөрөө батлах боломжгүй тул энэ багцын хуваарь гацна. Өөр батлагч нэмнэ үү.": "⚠️ The approver is the same person as the drafter — nobody can approve their own submission, so this package's schedule will stall. Add another approver.",
  "⚠️ Батлагч томилоогүй — илгээсэн хуваарийг хэн ч батлахгүй.": "⚠️ No approver assigned — nobody can approve a submitted schedule.",
  "«{0}» нэрээр хуучин хуваарилалт үлдсэн байна — «{1}» хуудсанд ✕ дарж арилгаад дахин нэмнэ үү.": "A previous assignment remains under the name “{0}” — remove it with ✕ on the “{1}” page, then add the account again.",
  "«{0}»-г хуваарийн хуваарилалтаас бүрэн хасах уу? «Хуваарь төлөвлөх» ба «Хуваарь батлах» эрх нь мөн буцаагдана.": "Remove “{0}” from the schedule assignment entirely? The “Plan schedule” and “Approve schedule” permissions will also be taken back.",
  "Хуваарилалт ArcGIS дээрх хуваалцсан хүснэгтэд хадгалагдаж, тухайн хүн өөрийн төхөөрөмжөөс нэвтрэхэд шууд үйлчилнэ. Үүрэг олгоход харгалзах эрх ба «Хуваарь» харагдац автоматаар нээгдэж, хасахад буцаагдана.": "Assignments are stored in the shared ArcGIS table and take effect as soon as the person signs in from their own device. Granting a role automatically grants the matching permission and the “Schedule” view; removing it takes both back.",
  "⚠️ Гүйцэтгэлийн урсгалаас ТУСДАА: хуваарийн үүрэг олгосон нь гүйцэтгэл зөвшөөрөх эрх өгөхгүй.": "⚠️ SEPARATE from the progress workflow: granting a schedule role gives no right to approve progress.",
  "Хуваарь батлах": "Approve schedule",
  "Сэлбэ порталын хуваарийн батлах урсгал": "Selbe portal — schedule approval workflow",
  "Батлах хүснэгт олдсонгүй — админд хандана уу.": "The approval table was not found — please contact an administrator.",
  "Энэ багцад батлагдаагүй илгээлт байна — эхлээд шийдвэрлүүлнэ үү.": "This package already has a submission awaiting approval — have it decided first.",
  "Өөрийн илгээсэн хуваарийг өөрөө батлах боломжгүй — өөр батлагч шийдвэрлэнэ.": "You cannot approve a schedule you submitted yourself — another approver must decide.",
  "Буцаах шалтгааныг бичнэ үү.": "Please state the reason for returning it.",
  "Илгээгдсэнгүй.": "Not submitted.",
  "Хуваарь батлуулахаар илгээгдлээ — батлагч шийдвэрлэнэ.": "The schedule has been submitted for approval — an approver will decide.",
  "Илгээлтийн агуулга уншигдсангүй — батлах боломжгүй.": "The submission content could not be read — approval is not possible.",
  "Шийдвэр хадгалагдсангүй.": "The decision was not saved.",
  "Хуваарь буцаагдлаа — гүйцэтгэгч засаад дахин илгээнэ.": "The schedule was sent back — the contractor will revise and resubmit.",
  "Хуваарь эх хуудсанд бичигдсэнгүй — илгээлт хүлээгдэж буй хэвээр.": "The schedule was not written to the source sheet — the submission is still pending.",
  "Хуваарь бичигдсэн ч төлөв шинэчлэгдсэнгүй — дахин оролдоно уу.": "The schedule was written but its status was not updated — please try again.",
  "Хуваарь батлагдаж эх хуудсанд бичигдлээ.": "The schedule was approved and written to the source sheet.",
  "Хуваарь батлагдлаа — эх хуудас аль хэдийн ижил байсан тул өөрчлөлт бичигдсэнгүй.": "The schedule was approved — the source sheet already matched, so no changes were written.",
  "Батлах хүснэгт бэлэн болоогүй — админ нэг удаа нэвтэрч үүсгэнэ.": "The approval table is not ready — an administrator creates it by signing in once.",
  "Өөрчлөлтийг батлуулахаар илгээнэ — батлагдтал эх хуваарь хөдлөхгүй": "Submit the changes for approval — the live schedule stays put until they are approved",
