  "Эрхийн тойм": "Permissions overview",
  "Багц бүрд хэн юу хариуцаж байгаа, хүн бүр юу хийж чадахыг нэг дэлгэцэнд. Ажил гацах эрсдэлийг урьдчилж хэлнэ.": "Who is responsible for each package, and what each person can do — on one screen. Warns in advance where work would stall.",
