  "Төслийн суурь тоо: нийт талбай, хүн ам, батлагдсан төсөвт өртөг": "Baseline project figures: total area, population and approved budget",
  "Багц бүрд шаардагдах зөвшөөрлийн бүртгэл. «Бүрдэлт» нь зөвшөөрөгдсөн нь нийтэд эзлэх хувь": "Register of the permits each package needs. “Completion” is the approved share of the total",
  "Эрх бүхий байгууллага «Зөвшөөрсөн» гэж шийдвэрлэсэн бичиг баримтын тоо": "Documents the competent authority has marked as approved",
  "Хүсэлт өгсөн ч шийдвэр гараагүй — гадны байгууллагад хүлээгдэж буй зөвшөөрөл": "Applied for but not yet decided — permits sitting with an external authority",
  "Зөвшөөрөөгүй, эсвэл төлөвийн утга нь толинд байхгүй тул баталгаажсан гэж үзэх боломжгүй": "Refused, or the status value is missing from the dictionary so it cannot be treated as approved",
  "Барилга эхлүүлэхийн өмнөх нөхцөл: нэгж талбар бүрийн чөлөөлөлтийн төлөв": "Precondition for starting construction: the clearance status of each parcel",
  "Эзэмшигчтэй тооцоо дууссан, барилга угсралт эхлэх боломжтой нэгж талбарууд": "Parcels settled with their owner, where construction can begin",
  "Хараахан чөлөөлөгдөөгүй нэгж талбар ба тэдгээрийн талбай — барилгыг хойшлуулж буй хүчин зүйл": "Parcels not yet cleared and their area — what is holding construction back",
  "Ажил бүрийн эхлэх, дуусах огноо. Хамралтын хувь нь багц бүрийг бүтнээр татдаг тул схемд бодогдохгүй": "Start and end dates for every task. Coverage is not computed here because it would pull every package in full",
  "Блокуудын биет гүйцэтгэл — «Гүйцэтгэл бөглөх» хуудсын мэдээллийг төсвийн жингээр жигнэсэн дундаж": "Physical progress of the blocks — the “Enter progress” sheet figures weighted by budget share",
  "Гүйцэтгэлийн хуудас нь бөглөгдсөн блокууд = нийт блок хасах тайлангүй блок": "Blocks whose fill sheet has been completed = total blocks minus unreported blocks",
  "ХАБЭА-гийн бүртгэлээр талбай дээр ажиллаж буй ажилтан ба техникийн тоо": "Workers and machines on site according to the HSE register",
  "ХАБЭА-д бүртгэгдсэн осол ба аюулгүй байдлын зөрчлийн тоо": "Accidents and safety violations recorded in the HSE register",
  "Талбай дээр шалгаж зөвшөөрөх эсвэл гүйцэтгэгч рүү буцаах ХОЁР дахь шат": "SECOND stage — inspects on site and either approves or returns it to the contractor",
  "Багцын хэмжээнд баталгаажуулах ГУРАВ дахь шат — буцаавал инженер рүү очно": "THIRD stage — confirms at package level; a return goes back to the engineer",
  "Батлагдсан төсөв. Блокийн гүйцэтгэлийн жин ч мөн эндээс тооцогдоно": "Approved budget. Block progress weights are derived from it as well",
  "Гүйцэтгэгчидтэй байгуулсан гэрээнүүдийн нийлбэр ба төсөвт эзлэх хувь": "Total of the contracts signed with contractors and its share of the budget",
  "IPC актаар бодитоор олгогдсон дүн ба төсөвт эзлэх хувь": "Amount actually disbursed through IPC certificates and its share of the budget",
  "Нэгтгэсэн үзүүлэлт. «Сүүлийн тайлангийн нас» нь мэдээлэл хэр шинэ болохыг хэлнэ": "Consolidated figures. “Age of the latest report” tells you how fresh the data is",
  "Мөнгөн дүн нь ихэвчлэн ТӨГРӨГӨӨР хадгалагдана — хариултад `₮` нэгжийг заавал бич, дүнг БҮТНЭЭР мянгатын таслалтай (товчлохгүй).": "Amounts are usually stored in TUGRIK — always state the `₮` unit in the answer and write the amount IN FULL with thousands separators (never abbreviate).",
  "Мөнгө, талбай, урт зэрэгт нэгжийг ҮРГЭЛЖ бич (м², км, ₮).": "Always give units for money, area and length (m², km, ₮).",
  "Санхүүгийн хувьд захирамжаар {0} ₮ батлагдсанаас {1} ₮{2} нь гэрээгээр баталгаажиж, {3} ₮{4} нь бодитоор олгогдсон байна.": "In financial terms, of the {0} ₮ approved by decree, {1} ₮{2} has been secured under contract and {3} ₮{4} has actually been disbursed.",
