  "«Гүйцэтгэл бөглөх»-ийн нийтлэгдээгүй ноорог": "Unpublished drafts for “Enter progress”",
  "Ноорог энэ хөтчид, мөн ArcGIS-д хадгалагдана — өөр компьютероос нэвтэрсэн ч сэргээх боломжтой. Хянагчид хүргэхийн тулд «Илгээх» дарна.": "The draft is saved in this browser and in ArcGIS — you can restore it after signing in from another computer. Press “Submit” to send it to reviewers.",
  "Ноорог хэт том тул зөвхөн энэ компьютерт хадгалагдлаа.": "The draft is too large, so it was saved on this computer only.",
