  "илгээлт · {0} мөр": "submission · {0} rows",
  "Баталсны дараа гүйцэтгэл архивт бичигдэж, нэгтгэлд бүртгэгдэнэ — үүнээс өмнө үндсэн өгөгдөлд ОРООГҮЙ": "Once approved, the progress is written to the archive and registered in the consolidation — until then it is NOT part of the main data",
  "Баталж архивт бүртгэх": "Approve and record in the archive",
  "Энэ багцад өөр хэрэглэгч илгээлт хийсэн байна — хуудсыг дахин ачаалж, ноорогоо сэргээгээд үргэлжлүүлнэ үү.": "Another user has already made a submission for this package — reload the page, restore your draft and continue.",
  "Хяналтад илгээв ({0}) · {1} нүд": "Submitted for review ({0}) · {1} cells",
  "Илгээлт хадгалагдлаа ({0} нүд) · ⚠️ хяналтад бүртгэгдсэнгүй: {1}": "The submission was saved ({0} cells) · ⚠️ but was not registered for review: {1}",
  "Илгээлт хадгалагдсан ч хяналтын бүртгэл ҮҮССЭНГҮЙ — хянагч үүнийг харахгүй.": "The submission was saved but NO review record was created — reviewers will not see it.",
  "Илгээлт «{0}» багцынх — хяналтын бүртгэл «{1}». Архивт юу ч бичсэнгүй.": "The submission belongs to package \"{0}\" but the review record says \"{1}\". Nothing was written to the archive.",
  "эхлэх": "start",
  "дуусах": "end",
  "«Шинэчлэгдсэн огноо» өөрчлөгдөнө ({0} → {1}) — батлахад БҮХ мөрийн төлөвлөгөөт гүйцэтгэл дахин бодогдоно.": "The \"Updated date\" will change ({0} → {1}) — approving it recalculates the planned progress of EVERY row.",
  "Хуваарийн огноо засагдсан: {0}": "Schedule dates edited: {0}",
  "Энэ илгээлт {0}-нд ДАХИН шинэчлэгдсэн — доор харагдаж буй нь ХАМГИЙН СҮҮЛИЙН агуулга, энэ мөрөнд илгээгдсэн үеийнх БИШ.": "This submission was updated AGAIN on {0} — what you see below is the LATEST content, NOT the version that was submitted for this record.",
  "Хяналтын үйлчилгээний талбаруудыг шалгаж чадсангүй — баталгаажуулалт хадгалагдах эсэх тодорхойгүй тул түр хаалттай.": "The review service fields could not be checked — it is unclear whether an approval would be saved, so this is disabled for now.",
  "«{0}»: архивт бичих жааз {1} мөр боловч лавлах {2} мөр байна — зөрүүтэй жааз бичвэл энэ багцын хуудас дараагийн ачаалалтад бүрмөсөн хаагдана. Архивт ЮУ Ч бичсэнгүй.": "\"{0}\": the snapshot to be written to the archive has {1} rows, but the reference is {2} — writing a mismatched snapshot would lock this package’s sheet out permanently on the next load. NOTHING was written to the archive.",
  "«{0}»: угсарсан жааз {1} мөр — ачаалсан {2} мөрөөс БОГИНО. Архивт ЮУ Ч бичсэнгүй.": "\"{0}\": the assembled snapshot has {1} rows — SHORTER than the {2} rows that were loaded. NOTHING was written to the archive.",
  "Бөглөх хуудасны «Б.» мөрийн гүйцэтгэл хэмжигдээгүй тул нэгтгэлд бичсэнгүй — хуудсаа шалгаад дахин баталгаажуулна уу.": "The “Б.” row of the fill sheet has no measured progress, so nothing was written to the summary — check the sheet and approve again.",
  "Нэгтгэлийн сүүлийн гүйцэтгэл {0}%, бөглөх хуудаснаас гарсан нь {1}% — хэт зөрүүтэй тул бичсэнгүй. Хуудасны хэмжээс (0–1 эсэх) ба «Б.» мөрийг шалгана уу.": "The latest progress in the summary is {0}%, but the fill sheet yields {1}% — too large a gap, so nothing was written. Check the sheet’s scale (0–1?) and its “Б.” row.",
