  "⚠️ ХУВЬ, ӨССӨН (хуримтлагдсан) дүн, суутгалын томьёо, төлөх дүн, зөрүү — эдгээр багана БАЙХГҮЙ. Хэрэгтэй бол мөрүүдээ татаад ӨӨРӨӨ бод; байхгүй багана нэрлэвэл хүсэлт унана. ": "⚠️ PERCENTAGES, CUMULATIVE amounts, deduction formulas, payable amounts and variances — these columns DO NOT EXIST. Compute them YOURSELF from the rows; naming a missing column makes the request fail. ",
