  "Гүйцэтгэгч байгууллага. ⚠️ Төлбөрийн хүснэгтийн {0}-тай бичиглэлээр (хашилт, зай) зөрж болно — нэрээр тулгаж БОЛОХГҮЙ, БАГЦААР тулга.": "Contractor organization. ⚠️ May differ in spelling (quotes, spaces) from {0} in the payments table — do NOT match by name, match BY PACKAGE.",
  "⚠️ Төлбөрийн хүснэгттэй (`ds:ipc`) холбох ГЭРЭЭНИЙ КОД ЭНД БАЙХГҮЙ. Тэнд `{0}` («Багц-1») гэсэн өөрийн гэрээний код бий ч ЭНЭ хүснэгтэд тэр код ОГТ байхгүй — хоёрыг холбох цорын ганц зам нь БАГЦЫН талбар ({0} → {1}). Нэг багцад олон гэрээ байж болохыг санаж, гэрээ тутмын нэгтгэл гаргах гэж бүү оролд. ": "⚠️ THE CONTRACT CODE that links to the payments table (`ds:ipc`) IS NOT HERE. That table has its own contract code `{0}` (“Багц-1”), but that code does NOT exist at all in THIS table — the only way to join the two is the PACKAGE field ({0} → {1}). Remember one package may hold several contracts, and do not attempt per-contract aggregation. ",
  "Хөрөнгө оруулалтын гүйцэтгэл — гүйцэтгэгчид олгосон санхүүжилт": "Investment performance — funding disbursed to contractors",
