  "Төсвийн эх үүсвэр — үнэт цаас, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Budget source — securities, ₮ (⚠️ contract-level, repeats)",
  "Төсвийн эх үүсвэр — борлуулалт, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Budget source — sales, ₮ (⚠️ contract-level, repeats)",
  "Гэрээний эх үүсвэр — үнэт цаас, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Contract source — securities, ₮ (⚠️ contract-level, repeats)",
  "Гэрээний эх үүсвэр — нийслэлийн төсөв, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Contract source — city budget, ₮ (⚠️ contract-level, repeats)",
  "Гэрээний эх үүсвэр — борлуулалт, ₮ (⚠️ гэрээний түвшний, давтагдана)": "Contract source — sales, ₮ (⚠️ contract-level, repeats)",
  "⚠️ СУУТГАЛ ЭНД БАЙХГҮЙ. `{0}` нь аль хэдийн БОДИТ ОЛГОСОН дүн. «Барьцаа», «урьдчилгааны эргэн төлөлт», «захиалагчийн/зохиогчийн хяналтын суутгал», «цэвэр дүн», «төлөгдөөгүй үлдэгдэл» гэсэн ойлголтууд энэ эх сурвалжид ОГТ бүртгэгддэггүй — асуувал «бүртгэгддэггүй» гэж хариул, бодож гаргах гэж бүү оролд. ": "⚠️ THERE ARE NO DEDUCTIONS HERE. `{0}` is already the ACTUAL DISBURSED amount. The concepts “retention”, “advance repayment”, “client/author supervision deduction”, “net amount” and “unpaid balance” are NOT recorded at all in this source — if asked, answer “not recorded” and do not try to derive them. ",
  "⚠️ АКТЫН ТӨЛӨВ БАЙХГҮЙ. «Хянагдаж байна», «батлагдсан», «хугацаа хэтэрсэн», «төлөх ёстой огноо» — бүгд алга. Мөр бүр нь АЛЬ ХЭДИЙН хийгдсэн гүйлгээ. ": "⚠️ THERE IS NO CERTIFICATE STATUS. “Under review”, “approved”, “overdue”, “due date” — none exist. Every row is a transaction that has ALREADY been executed. ",
  "⚠️ Талбарын нэр `{0}` нь ДООД ЗУРААСТАЙ (толинд `on` гэж бичигдсэн ч үйлчилгээнд өөр) — `on` гэж бичвэл хүсэлт УНАНА. ": "⚠️ The field name `{0}` has a TRAILING UNDERSCORE (the dictionary shows `on`, but the service differs) — writing `on` will make the query FAIL. ",
  "⚠️ Огноо БҮГД `DateOnly` — «2026-06-08» гэсэн МӨР, epoch мс БИШ. Сарыг эхний 7 тэмдэгтээс ав. ": "⚠️ ALL dates are `DateOnly` — a STRING like “2026-06-08”, NOT epoch ms. Take the month from the first 7 characters. ",
