  "Олгосон байгууллагатай яаралтай уулзаж татгалзсан үндэслэлийг тодруулан, шаардлагатай нэмэлт материалыг бүрдүүлж дахин хүсэлт гаргах.": "Meet the issuing authority without delay, establish the grounds for refusal, assemble the additional documents required and re-apply.",
  "Холбогдох байгууллагуудаас хариу өгөх хугацааг баталгаажуулж, шаардлагатай бол зохицуулах хурал зарлан шийдвэрлэх хугацааг товлох.": "Confirm response deadlines with the relevant authorities and, if needed, convene a coordination meeting to set a decision date.",
  "Санхүүжилтийн графикийг гэрээний хуваарьтай уялдуулан дахин хянаж, олголтын саатлын шалтгааныг багц тус бүрээр тодруулах.": "Review the disbursement schedule against the contract timetable and establish the cause of delay for each package.",
  "Санхүүжилтийн эрэмбийг тухайн ажлын эхлэх хуваарьтай уялдуулан дахин харах; олголт огт эхлээгүй багцуудын явцыг сар бүр хянах.": "Re-prioritise funding in line with the works’ start dates and review packages with no disbursement monthly.",
  "Үлдэгдэл ажлын гүйцэтгэгч сонгон шалгаруулах, гэрээ байгуулах ажлыг эрчимжүүлж төлөвлөгөөт хугацаанд багтаах.": "Accelerate contractor selection and contracting for the remaining works so they stay within the planned timetable.",
  "Үлдсэн талбаруудад зориулсан хэлэлцээрийн баг байгуулж, гол шалтгаан тус бүрээр шийдвэрлэх хугацаатай зорилт тавих.": "Form a negotiation team for the remaining parcels and set a dated target for resolving each main obstacle.",
  "Эдгээр багцын ажил эхлэхэд саад болж буй хүчин зүйлийг (зөвшөөрөл, газар, санхүүжилт) тус бүрд нь тодруулж, хариуцагч томилох.": "Establish, for each of these packages, what is blocking the start of work (permits, land, funding) and assign an owner.",
  "Хоцрогдолтой блокуудад хүн хүч, техник хэрэгслийн нэмэлт хуваарилалт хийж, сар бүрийн биет хэмжилтээр явцыг хянах.": "Allocate additional workforce and equipment to the blocks behind schedule and track progress through monthly physical measurement.",
  "Одоогийн хурдыг барихын тулд хүн хүч, техник хэрэгслийн хуваарилалтыг тогтвортой хадгалж, хамгийн бага гүйцэтгэлтэй багцуудад нэмэлт анхаарал хандуулах.": "Keep workforce and equipment allocation steady to hold the current pace, and give extra attention to the packages with the lowest progress.",
  "{0} хасагдсан ажил тоонд ороогүй": "{0} removed works not counted",
