  "Гэрээлсэн нийт дүнгийн {0}-д санхүүжилт олгогдсон байна.{1}{2}": "{0} of the total contracted amount has been disbursed.{1}{2}",
  " Доор санхүүжилт эхэлсэн {0} багцыг үзүүлэв; гэрээт боловч олголт огт хийгдээгүй {1} багцыг хавсралтад жагсаав.": " The {0} packages with disbursement are shown below; the {1} contracted packages with no disbursement yet are listed in the appendix.",
