  "«Гэрээ байгуулаагүй ажил» гэдэг нь зөвхөн төсөвт өртөгтэй, гэрээ хараахан байгуулагдаагүй багцууд; гэрээлсэн дүнд орохгүй, нэрс ба төсвийг хавсралтаас үзнэ үү.": "“Works without a contract” are packages that only have a budget estimate and no contract yet; they are excluded from the contracted amount — see the appendix for names and budgets.",
