  "Багц тус бүрийн санхүүжилт (олгосон ба гэрээлсэн дүн)": "Financing by package (disbursed and contracted amount)",
  "огноогүй": "no date",
  "{0} нүд илгээснээс хойш өөр замаар өөрчлөгдсөн байна (зэрэгцээ өөрчлөлт). Батлах боломжгүй — буцааж, зохиогч шинэ хуваарин дээр дахин илгээнэ.": "{0} cells were changed elsewhere after submission (concurrent edit). Cannot approve — return it, and the author resubmits on the new schedule.",
  "Илгээлтээ татах уу? Батлагч шийдвэрлэхээ болино; агуулга нь ноорог болж буцна.": "Withdraw the submission? The approver will no longer decide on it; its content returns to your draft.",
  "Илгээлт татагдсангүй.": "The submission was not withdrawn.",
  "Илгээлт татагдлаа — агуулга ноорог болж буцлаа; {0} нүд хооронд нь өөр замаар өөрчлөгдсөн тул шалгаад дахин илгээнэ үү.": "Submission withdrawn — its content is back in your draft; {0} cells were changed elsewhere in the meantime, please review and resubmit.",
  "Илгээлт татагдлаа — агуулга ноорог болж буцлаа, засаад дахин илгээж болно.": "Submission withdrawn — its content is back in your draft; edit and resubmit.",
  "Илгээлт татагдлаа. Агуулга нь ноорогт буусангүй (төрөл зөрсөн эсвэл уншигдсангүй).": "Submission withdrawn. Its content could not be restored to the draft (type mismatch or unreadable).",
