  "Захирамжаар батлагдсан дүнгийн {0} нь гэрээгээр баталгаажсан бөгөөд гэрээлсэн дүнгийн {1} нь бодитоор олгогдсон байна. Олгогдоогүй үлдэгдэл {2} ₮ байна.": "{0} of the amount approved by decree is secured by contracts, and {1} of the contracted amount has actually been disbursed. The undisbursed balance is {2} ₮.",
  "Нийт олгосон {0} ₮-ийн {1} ₮ нь гэрээлсэн багцад холбогдоогүй (олон багц хамарсан эсвэл гэрээ баталгаажаагүй багцын) төлбөр тул дээрх хувь, үлдэгдэлд ороогүй.": "Of the {0} ₮ disbursed in total, {1} ₮ are payments not tied to a contracted package (spanning several packages or for a package without a confirmed contract), so they are excluded from the share and balance above.",
  "Орон сууцны гүйцэтгэл (багцаар, төсвийн жинтэй) нь {0} блокийг багцынх нь төсвийн жингээр тооцсон дүн (3-р хэсэг); барилга угсралтын гүйцэтгэл нь хяналтын {1} блокийн энгийн дундаж (6-р хэсэг).": "Housing progress (by package, budget-weighted) aggregates {0} blocks by their package's budget weight (section 3); construction progress is the simple average of the {1} monitored blocks (section 6).",
  "Гэрээлсэн": "Contracted",
  "Хоногийн сүүлийн заалт ба өмнөх хоногийн сүүлийн заалтын ЗӨРҮҮ — тухайн хоногт хэрэглэсэн бодит эзлэхүүн.": "DIFFERENCE between the day's last reading and the previous day's last reading — the actual volume consumed that day.",
  "Энэ цэгт (дээд гүн)": "At this point (max depth)",
  "{0} ажлын сарын задаргаа обьёмтойгоо тэнцэхгүй байна (хоосон задаргаа = 0): {1}. Тухайн ажлын цонхыг нээж сараар тэнцүүлнэ үү.": "The monthly breakdown of {0} works does not match their volume (an empty breakdown = 0): {1}. Open each work's dialog and balance it by month.",
  "Илгээлтийн агуулга уншигдсангүй — татсангүй, дахин оролдоно уу.": "The submission's content could not be read — not withdrawn, please try again.",
  "Энэ илгээлт ГЭРЭЭНИЙ огноонд хамаарна — «Гэрээ» таб руу шилжээд татна уу.": "This submission belongs to CONTRACT dates — switch to the “Contract” tab to withdraw it.",
  "Энэ илгээлт ТӨЛӨВЛӨГӨӨНИЙ огноонд хамаарна — «Төлөвлөгөө» таб руу шилжээд татна уу.": "This submission belongs to PLAN dates — switch to the “Plan” tab to withdraw it.",
