  "Татах хүсэлтийн хариу алдагдсан — илгээлт татагдаагүй, хүлээгдсэн хэвээр. Дахин оролдоно уу.": "The withdraw response was lost — the submission was NOT withdrawn and is still pending. Please retry.",
  "Татах хүсэлтийн хариу алдагдсан — татагдсан эсэх тодорхойгүй. Мөрүүдийг энэ компьютерт хадгалав; хуудсаа шинэчлэхэд шийдэгдэнэ.": "The withdraw response was lost — it is unclear whether it was withdrawn. The rows were kept on this computer; refreshing the page will resolve it.",
  "Таны түгжээний хугацаа дууссан — юу ч бичигдсэнгүй. Дахин оролдоно уу.": "Your lock expired — nothing was written. Please retry.",
  "Нэмсэн шинэ ажлын мөрийг батлуулахаар илгээнэ — батлагдтал үндсэн өгөгдөлд бичигдэхгүй": "Submit the new work rows for approval — nothing is written to the main data until approved",
