  "Нэмэлт ажил буцаагдлаа — нэмэгч засаад дахин илгээнэ.": "Extra work sent back — the author will amend and resubmit.",
  "Таны багцуудад батлах нэмэлт ажил алга.": "No extra work to approve in your packages.",
  "Энэ багцын түлхүүр бүртгэлд алга — батлах боломжгүй. Буцаавал нэмэгч зөв багцаар дахин илгээнэ.": "This package key is not in the registry — approval is not possible. Return it and the author will resubmit under the correct package.",
  "Илгээлтийн агуулга уншигдсангүй — батлах боломжгүй. Буцаавал нэмэгч дахин илгээнэ.": "The submission content could not be read — approval is not possible. Return it and the author will resubmit.",
