  "{0} мөрийг батлах уу? Батлагдмагц мөрүүд үндсэн хүснэгтэд шууд бичигдэнэ — «Хуваарь» ба «Гүйцэтгэл бөглөх» хоёуланд гарна.": "Approve {0} rows? Once approved they are written to the source table immediately — visible in both “Schedule” and “Enter progress”.",
