  "Батлагдсан, гэвч хуудсанд буулгаж чадсангүй: {0} — «Батлагдсан · буулгаагүй» хэсгээс дахин буулгана уу.": "Approved, but could not be applied to the sheet: {0} — apply again from the “Approved · not applied” section.",
  "Мөрүүд аль хэдийн хуудсанд байна — «буулгасан» гэж тэмдэглэв.": "The rows are already on the sheet — marked as applied.",
  "Хуудсанд орлоо — {0} мөр үндсэн хүснэгтэд бичигдэв.": "Applied — {0} rows written to the source table.",
  "Хуудсанд буулгаж чадсангүй: {0}": "Could not apply to the sheet: {0}",
  "Илгээлтээ татах уу? Батлагч шийдвэрлэхээ болино; мөрүүдээ «Хуваарь» хуудсанд дахин нэмнэ.": "Withdraw the submission? The approver will no longer decide on it; re-add the rows on the “Schedule” page.",
  "Илгээлт татагдлаа — «Хуваарь» хуудсанд дахин нэмж илгээнэ үү.": "Submission withdrawn — re-add and resubmit on the “Schedule” page.",
  "«Хуваарь» хуудаснаас ирсэн, батлахыг хүлээж буй шинэ ажлын мөрүүд — батлагдмагц үндсэн хүснэгтэд бичигдэнэ": "New work rows submitted from the “Schedule” page, awaiting approval — written to the source table once approved",
  "Батлах нэмэлт ажил алга — «Хуваарь» хуудаснаас илгээмэгц энд гарч ирнэ.": "No extra work to approve — it appears here as soon as it is submitted from the “Schedule” page.",
  "Батлагдсан · буулгаагүй": "Approved · not applied",
  "Эдгээр илгээлт батлагдсан боловч үндсэн хүснэгтэд бичигдээгүй (сүлжээ, зэрэгцээ батлалт). «Дахин буулгах» дарна уу — давхар мөр үүсэхгүй.": "These submissions were approved but not written to the source table (network, concurrent approval). Press “Apply again” — no duplicate rows will be created.",
  "Батлагдсан": "Approved",
  "Батлагдмагц мөрүүд үндсэн хүснэгтэд шууд бичигдэнэ.": "Once approved, the rows are written to the source table immediately.",
  "Батлагдсан мөрүүдийг үндсэн хүснэгтэд дахин бичнэ — аль хэдийн байгаа мөр давхардахгүй": "Writes the approved rows to the source table again — existing rows are not duplicated",
  "Дахин буулгах": "Apply again",
  "Энэ мөр батлагдаагүй нэмэлт ажил — батлагдсаны дараа уялдаа тавина.": "This row is unapproved extra work — set dependencies after approval.",
  "Нэмэлт ажил батлагдаж хуудсанд орлоо — мөрүүд серверээс шинэчлэгдэв.": "Extra work approved and applied — rows refreshed from the server.",
  "Илгээлтээ татах уу? Батлагч шийдвэрлэхээ болино; мөрүүд хуудсанд буцаж орно.": "Withdraw the submission? The approver will no longer decide on it; the rows return to the sheet.",
  "«{0}» нэмэгдлээ — «Нэмэлт ажил батлуулах» товчоор батлуулна; батлагдмагц үндсэн хүснэгтэд бичигдэнэ.": "“{0}” added — submit with “Submit extra work”; once approved it is written to the source table.",
  "Батлагдсан нэмэлт ажлын {0} илгээлт үндсэн хүснэгтэд хараахан буугаагүй — батлагч «Нэмэлт ажил батлах» хуудаснаас «Дахин буулгах» дарна.": "{0} approved extra-work submissions are not yet written to the source table — an approver presses “Apply again” on the “Approve extra work” page.",
  "Батлагдаагүй шинэ ажил — батлагдсаны дараа хуваарь тавина": "Unapproved new work — schedule it after approval",
  "Ачаалснаас хойш хуудсанд шинэ мөр орлоо (өөр батлалт зэрэг явсан) — юу ч бичсэнгүй, дахин оролдоно уу.": "New rows entered the sheet since loading (a concurrent approval) — nothing written, please try again.",
  "Бичсэний дараа хуудсанд өөр жааз орлоо (зэрэгцээ батлалт) — төлөв «батлагдсан» хэвээр, дахин оролдоно уу.": "Another frame entered the sheet after writing (a concurrent approval) — status stays “approved”, please try again.",
  "Хуудас шинэчлэгдлээ — хадгалаагүй ноорог шинэ мөрүүд рүү зөөгдөв.": "Sheet refreshed — the unsaved draft was moved to the new rows.",
  "Нэмэлт ажил батлагдлаа — хадгалаагүй өөрчлөлтөө хадгалаад/илгээгээд хуудсыг шинэчилнэ үү.": "Extra work was approved — save or submit your unsaved changes, then refresh the sheet.",
  "Хуудсыг серверээс татна; хадгалаагүй ноорог шинэ мөрүүд рүү (№ · нэрээр) зөөгдөнө": "Reloads the sheet from the server; the unsaved draft is moved to the new rows (by № · name)",
  "Ачаалснаас хойш хуудасны мөрүүд засагдлаа (хуваарь зэрэг хадгалагдсан) — юу ч бичсэнгүй, дахин оролдоно уу.": "Sheet rows were edited after loading (a schedule was saved concurrently) — nothing was written, please try again.",
  "серверээс үр дүн дутуу ирлээ": "the server returned incomplete results",
  "Батлагдаж архивт бичигдлээ, гэхдээ гүйцэтгэлээс IPC мөр үүсгэж чадсангүй ({0}). Тухайн сарын IPC-г админд мэдэгдэж шалгуулна уу.": "Approved and written to the archive, but the IPC row could not be created from the progress data ({0}). Please ask an admin to check that month's IPC.",
  "Давхар IPC мөрийг нэгтгэж чадсангүй": "Could not merge the duplicate IPC row",
  "IPC зөрүү {0}/{1} мөрд бичигдсэнгүй": "IPC difference was not written for {0}/{1} rows",
  "Хогийн сав, ус, гэрэлтүүлэг, темп, хөрс": "Waste bins, water, lighting, temperature, soil",
