  "Өөрчлөгдсөн мөр улаан хүрээтэй · хуучин огноо нь зурвасын доор бүдгээр · ажлын кодын ✕ дээр дарж зөвшөөрнө (ногоон ✓) · нэр дээр дарж дэлгэрэнгүйг харна · бүгд ногоон болсны дараа «Батлах» идэвхжинэ": "Changed rows are outlined red · the current dates show faintly under the bar · click ✕ on the work code to approve (green ✓) · click the name for details · “Approve” enables once all are green",
