  "«{0}» устгагдсан аккаунт — өөрчлөлт хадгалагдсангүй.": "“{0}” is a deleted account — the change was not saved.",
  "Мөр = багц, багана = шат. «+»-ээр аккаунт нэмж, ✕-ээр хасна. Нэг аккаунт зөвхөн НЭГ шатанд байна — өөр шатанд нэмбэл шилжүүлэхийг асууна.": "Rows = packages, columns = stages. Add an account with “+”, remove it with ✕. An account belongs to only ONE stage — adding it to another stage asks to move it.",
  "Хадгалаагүй өөрчлөлт байна — хэл солиход алдагдана. Солих уу?": "You have unsaved changes — switching the language will discard them. Switch anyway?",
  "{0}: хадгалаагүй засвар байна. Гарвал алдагдана. Гарах уу?": "{0}: there are unsaved edits. They will be lost if you leave. Leave anyway?",
  "{0}: бичилт явж байна — одоо гарвал дундаа тасарч болзошгүй. Гарах уу?": "{0}: a write is in progress — leaving now may interrupt it midway. Leave anyway?",
  "Төлөвлөсөн обьём: «{0}» — тоо биш, тодорхойгүй эсвэл сөрөг тул бичигдсэнгүй. 1250 эсвэл 1.25 гэж бичнэ үү.": "Planned volume: “{0}” is not a number, is ambiguous or negative — not saved. Enter e.g. 1250 or 1.25.",
  "{0} нүд бичигдлээ · {1} утгыг тоо гэж уншиж чадсангүй (тодорхойгүй таслал «1,250», сөрөг эсвэл тоо биш) — бичигдсэнгүй: {2}": "{0} cells written · {1} values could not be read as numbers (ambiguous comma “1,250”, negative or non-numeric) — not written: {2}",
