  "Хохирлын муж нь загварчлалын {0} м-ээс гүн усны мөр. Хохирол нь ангиллын нэгж үнийн ТААМАГ; «*» — өртөг тодорхойгүй давхарга нийтэд ороогүй.": "Damage zone = simulated footprint of water deeper than {0} m. Damage is an ESTIMATE from class unit rates; “*” — layers with unknown cost are not in the total.",
