  "Хянагчийн {0} зөвшөөрлийг энэ хуудасны мөрүүдтэй тулгаж чадсангүй (хуучин хэлбэр эсвэл хүснэгт өөрчлөгдсөн) — аль нүд зөвшөөрөгдсөнийг баталж чадахгүй тул улаан хүрээтэй нүдийг дахин хянах шаардлагатай.": "Could not match {0} reviewer approvals to this sheet’s rows (old format or table changed) — approved cells cannot be confirmed, so the red-framed cells need re-review.",
  "Буулгалтын урьдчилсан харагдац: {0} нүд бичигдэнэ (цэнхэр), {1} нүд татгалзагдана (улаан ✕ — нүдэн дээр шалтгаан нь).": "Paste preview: {0} cells will be written (blue), {1} rejected (red ✕ — reason on the cell).",
