  "гэрээлсэн багцаас гадуур олгосон {0} (хувьд ороогүй)": "paid {0} outside contracted packages (not in %)",
  "{0} энэ багцын хуваарийг түрүүлж илгээсэн байна — таны илгээлт цуцлагдлаа. Эхлээд шийдвэрлүүлнэ үү.": "{0} submitted this package's schedule first — your submission was cancelled. Get it decided first.",
  "Өөр хэрэглэгч": "Another user",
  "Энэ илгээлтийн хуваарийг батлагч ({0}) эх хуудсанд ХЭСЭГЧЛЭН бичсэн — буцаах боломжгүй. «Батлах»-ыг дахин дарж бичилтийг гүйцээнэ үү.": "Approver ({0}) has PARTIALLY written this submission's schedule to the source sheet — it cannot be returned. Press “Approve” again to complete the write.",
  "Батлагч ({0}) энэ илгээлтийн хуваарийг эх хуудсанд ХЭСЭГЧЛЭН бичсэн — татах боломжгүй. Батлагч батлалтыг гүйцээнэ.": "Approver ({0}) has PARTIALLY written this submission's schedule to the source sheet — it cannot be withdrawn. The approver will complete the approval.",
  "Хагас бичилтийн хамгаалалтын тэмдэг хадгалагдсангүй ({0}) — эх хуудсанд юу ч бичигдсэнгүй; дахин оролдоно уу.": "The partial-write protection marker was not saved ({0}) — nothing was written to the source sheet; please try again.",
  "{0} ажил·блокийн сарын задаргааны ажил хуудсанд олдсонгүй": "monthly breakdown tasks for {0} task·block(s) were not found on the sheet",
  "Хуваарь эх хуудсанд бичигдсэн тул буцаах боломжгүй — «Батлах»-ыг дахин дарж дуусгана уу.": "The schedule is already written to the source sheet, so it cannot be returned — press “Approve” again to finish.",
  "дундаж = бүх блокоор (тайлангүй блок 0%)": "average over all blocks (unreported blocks count as 0%)",
  "сараар · бүх блокийн сүүлийн утгаар (тайлангүй блок 0%)": "monthly · latest value of all blocks (unreported blocks count as 0%)",
  "Гүйцэтгэл нь огт бөглөгдөөгүй блокууд. Багцын болон дундаж гүйцэтгэлд 0%-иар орно": "Blocks with no progress entered. They count as 0% in the package and average progress",
  "Ноорог энэ компьютерт — алсад хараахан хадгалагдаагүй": "Draft saved on this computer — not yet saved to the server",
  "Ноорог энэ хөтчид хадгалагдсангүй (сан дүүрсэн эсвэл хаалттай) — зөвхөн ArcGIS-д хуулагдана. Таб хаахаас өмнө «Илгээх» дарах эсвэл хөтчийн сан чөлөөлнө үү.": "Draft was not saved in this browser (storage full or blocked) — it is only copied to ArcGIS. Press “Send” or free browser storage before closing the tab.",
  "{0} нүд илгээгдсэний ДАРАА засагдсан байсан — давхар тоологдохгүйн тулд илгээгдсэн хэсгийг хасаж ЗӨРҮҮГ нь үлдээв. Ногоон нүдийг шалгаад дахин илгээнэ үү.": "{0} cell(s) were edited AFTER being sent — to avoid double counting the sent part was subtracted and only the DIFFERENCE was kept. Check the green cells and send again.",
  "Ноорогийн {0} нүдийг аль мөрөнд буулгахаа тодорхойлж чадсангүй (ижил нэртэй мөр олон, хүснэгт шинэчлэгдсэн) — буруу мөрөнд бичихгүйн тулд сэргээсэнгүй; ноорогт хадгалагдсан хэвээр. Тэр ажлуудыг шалгаж гараар дахин бөглөнө үү.": "Could not determine which row {0} draft cell(s) belong to (several rows share the same name and the sheet was updated) — not restored to avoid writing to the wrong row; they remain in the draft. Check those works and re-enter them manually.",
  "Ноорогийн {0} огноо/утга ноорог бичигдсэнээс хойш серверт өөрчлөгдсөн тул хуучин утгаар дарсангүй — шалгаад шаардлагатай бол дахин оруулна уу.": "{0} draft date(s)/value(s) changed on the server after the draft was written, so the old value was not applied — check and re-enter if needed.",
  "Өмнөх багцын сүүлийн засвар ArcGIS-т хуулагдсангүй ({0}) — энэ компьютерт хадгалагдсан; тэр багцыг дахин нээхэд автоматаар илгээнэ. Тэр болтол өөр компьютероос бүү бөглө.": "The last edits of the previous package were not copied to ArcGIS ({0}) — they are saved on this computer and will be sent automatically when that package is opened again. Until then, do not fill it from another computer.",
  "Өмнөх «Илгээх» сервер дээр АМЖИЛТТАЙ хадгалагдсан байсан (хариу нь тасарсан) — илгээгдсэн нүдийг ноорогоос хасав, давхар илгээгдэхгүй.": "The previous “Send” had in fact been SAVED on the server (its response was lost) — the sent cells were removed from the draft and will not be sent twice.",
  "Инженерийн төлөвлөсөн обьём (ноорогт хадгалагддаггүй)": "Engineer planned volume (not saved in the draft)",
  "Гүйцэтгэл бөглөх (энэ компьютерт хадгалагдсангүй)": "Enter progress (not saved on this computer)",
  "Энэ ноорог {0}-ны буцаасан илгээлтийн засвар — «Өмнөх өдрийн илгээлт буцаасан» мэдэгдлээс тэр илгээлтийг сонгоод илгээнэ үү, эсвэл ноорогоо устгана уу.": "This draft is a correction of the sent-back submission of {0} — select that submission from the “previous day's submission sent back” notice and send, or discard the draft.",
  "Өмнөх «Илгээх» сервер дээр АМЖИЛТТАЙ хадгалагдсан байсан (хариу нь тасарсан). Түүнээс хойш засагдсан {0} нүдийг ЗӨРҮҮ болгож үлдээв — шалгаад дахин илгээнэ үү.": "The previous “Send” had in fact been SAVED on the server (its response was lost). {0} cell(s) edited since then were kept as the DIFFERENCE — check and send again.",
  "Өмнөх «Илгээх» сервер дээр АМЖИЛТТАЙ хадгалагдсан байсан (хариу нь тасарсан) — давхар илгээсэнгүй.": "The previous “Send” had in fact been SAVED on the server (its response was lost) — nothing was sent twice.",
  "Гүйцэтгэл илгээж байна": "Sending progress",
  "Энэ ноорог {0}-ны буцаасан илгээлтийн засвар — өнөөдрийн илгээлтэд нийлүүлэхгүйн тулд «Илгээх» түгжээтэй. Тэр илгээлтийг сонгоно уу, эсвэл ноорогоо устгана уу.": "This draft is a correction of the sent-back submission of {0} — “Send” is locked so it is not merged into today's submission. Select that submission or discard the draft.",
  "Тэр илгээлтийг сонгох": "Select that submission",
