  "«Тавих» дарахад энэ блокийн уялдаа сонгосон {0} блокт хуулагдана": "On “Apply”, this block's dependencies are copied to the {0} selected blocks",
  "Чирж жагсаалтыг өргөсгөнө · давхар дарвал анхны өргөн": "Drag to widen the list · double-click to reset",
  "Бүх блок": "All blocks",
  "Блок бүрээр харах · засах горим руу буцна.": "Return to per-block view · editing mode.",
  "Бүх блокийн хуваарийг ажил бүрийн доор зэрэг харуулна (зөвхөн харах).": "Show every block's schedule under each task at once (view only).",
  "Бүх блок — зөвхөн харах. Ажлын зурвас нь бүх блокийн нийт муж; доорх мөрүүд блок бүрийнх. Блокийн мөр дээр дарж тэр блок руу орж засна.": "All blocks — view only. A task's bar is the combined span of all blocks; the rows below are per block. Click a block row to open that block for editing.",
  "Дарж «{0}» блок руу орж засна": "Click to open block “{0}” for editing",
  "{0} мөрийн уялдааны бичиглэл {1} тэмдэгтээс урт тул хадгалагдсангүй. Блок тус бүрийн уялдааг цөөлөх эсвэл бүх блокт нэг уялдаа болгоно уу.": "Dependencies on {0} row(s) are longer than {1} characters, so nothing was saved. Reduce the per-block dependencies or use one dependency for all blocks.",
  "Уялдааны бичиглэл {0} тэмдэгт — талбарт {1} хүртэл багтана. Блок цөөлөх эсвэл бүх блокийг сонгож нэг уялдаа болгоно уу.": "The dependency text is {0} characters — the field holds up to {1}. Select fewer blocks, or select all blocks to use a single dependency.",
  "Уялдааны бичиглэл талбарт багтахгүй ({0} > {1} тэмдэгт)": "The dependency text does not fit the field ({0} > {1} characters)",
  "Бүгдийг хураах — зөвхөн дээд түвшний бүлгүүд": "Collapse all — top-level groups only",
  "«Бүх блок» горимд ч PDF зөвхөн идэвхтэй блокийг ({0}) агуулна.": "Even in “All blocks” mode, the PDF contains only the active block ({0}).",
  "Өмнөх илгээлтийн {0} нүдийг шинэ хүснэгтийн мөрөнд тулгаж чадсангүй (ижил нэртэй мөр олон эсвэл мөр хасагдсан): {1}. Тэдгээрийг өмнөх илгээлтээс ХАСААД үргэлжлүүлэх үү? (Үгүй — илгээхгүй, ноорог хэвээр.) Хассан нүдийг дараа нь гараар дахин бөглөнө үү.": "{0} cell(s) of the previous submission could not be matched to rows of the updated sheet (several rows share the same name, or rows were removed): {1}. REMOVE them from the previous submission and continue? (Cancel — nothing is sent, the draft is kept.) Re-enter the removed cells manually afterwards.",
  "{0} нүдэнд илгээгдсэн утгатай ИЖИЛ утга илгээлтийн дараа дахин бичигдсэн байсан — давхар тоологдохгүйн тулд хасав. Энэ нь шинэ нэмэлт ажил байсан бол тэр нүдийг дахин бөглөнө үү.": "{0} cell(s) were written again after sending with the SAME value as was sent — removed to avoid double counting. If this was new additional work, fill those cells again.",
  "Энэ компьютерт 7 хоногоос удаан ArcGIS-т хуулагдаагүй үлдсэн {0} нүдийг сэргээсэнгүй — тэр хооронд илгээгдсэн байж болох тул автоматаар нэмбэл ДАВХАР тоологдоно. Шалгаад шаардлагатай бол гараар дахин бөглөнө үү.": "{0} cell(s) that stayed on this computer for more than 7 days without being copied to ArcGIS were not restored — they may have been sent meanwhile, so adding them automatically could DOUBLE count. Check and re-enter manually if needed.",
  "Тэмдэглэсэн нүд 7 хоногийн дараа автоматаар хаягдана — «Тэмдэглэсэн нүдийг хаях» товчоор одоо хаяж болно.": "Flagged cells are discarded automatically after 7 days — use “Discard flagged cells” to discard them now.",
  "Ноорогт сэргээгээгүй {0} нүд тэмдэглэгдсэн байна (аль мөр нь тодорхойгүй, серверт өөрчлөгдсөн эсвэл хуучирсан) — 7 хоногийн дараа автоматаар хаягдана.": "{0} draft cell(s) are flagged and not restored (row unclear, changed on the server, or stale) — they are discarded automatically after 7 days.",
