  "Багцын хуваарь хэмжилтийн өдөр хараахан эхлээгүй — гүйцэтгэлийн оноо тавигдахгүй (гэрээний огнооны шугамаар орлуулахгүй).": "The package schedule had not started on the measurement date — no performance score (not replaced by the contract-date line).",
  "Хуваарь {0} хамарсан — гүйцэтгэлийн оноо тавигдахгүй (огноогүй ажлын жин төлөвлөгөөнд 0-ээр орж «төлөвлөсөн» хэт бага гардаг). Багцын хуваарийг бүрэн бөглөнө үү.": "The schedule covers only {0} — no performance score (undated tasks count as 0 in the plan, so “planned” comes out far too low). Please complete the package schedule.",
  "Нийт олгосон дүнд гэрээлсэн багцаас гадуурх {0} ₮ олголт (хэд хэдэн багц хамарсан мөр, гэрээлсэн дүнгийн багцад холбогдоогүй төлбөр) орсон — олгосон хувьд ороогүй.": "Total disbursed includes {0} ₮ paid outside the contracted packages (multi-package rows, payments not linked to a contracted package) — not included in the disbursed share.",
