  "Эцэг бүлэг хуудсанд олдсонгүй — дахин буулгах боломжгүй. Нэмэгчид буцаана уу.": "The parent group was not found on the sheet — re-applying cannot succeed. Return it to the submitter.",
  "Илгээлтийг шалтгаантай нь нэмэгчид буцаана — тэр засаад дахин илгээнэ": "Returns the submission with the reason to the submitter — they fix and resubmit it",
  "Нэмэгчид буцаах": "Return to submitter",
  "Cashflow хүснэгтийн утга засах ба мөр нэмэх эрх — аккаунтаар, тус тусад нь олгоно.": "Rights to edit values and add rows in the Cashflow table — granted per account, separately.",
  "«Санхүүжилт» харагдацын Cashflow (/173) хүснэгтийн нүдний утга ба Cashflow хуваарилалтыг засах. Энэ нь дашбоардын санхүүгийн тооны эх сурвалж тул нэг нүд засахад 02, 08 дашбоард, тайлан бүгд дагаж өөрчлөгдөнө. IPC нь гүйцэтгэлийн батлалтаас автоматаар үүсдэг — энэ эрхээр засагдахгүй.": "Edit cell values of the Cashflow (/173) table and the Cashflow allocation in the “Financing” view. It is the source of the dashboard financial figures, so editing one cell changes dashboards 02, 08 and the reports. IPC is generated automatically from performance approvals — this right does not edit it.",
  "Cashflow хүснэгтэд шинэ мөр нэмэх. Байгаа мөрийн утгыг засахад «утга засах» эрх тусдаа хэрэгтэй. Мөр устгах боломжгүй.": "Add new rows to the Cashflow table. Editing values of existing rows needs the separate “edit values” right. Rows cannot be deleted.",
  "Илгээлтийн {0} нүдийг хуудсанд буулгаж чадсангүй — мөр нь одоогийн хуудсанд тулгагдаагүй, эсвэл нэмэлтийн утга нь тоо биш («1,250» · «abc» мэт). Доорх жагсаалтад харагдахгүй бөгөөд батлах боломжгүй — гүйцэтгэгчээр шалгуулж (тоог зөв бичээд) дахин илгээлгэнэ үү.": "{0} cell(s) of the submission could not be placed on the sheet — either the row was not matched to the current sheet, or the increment value is not a number (e.g. “1,250” · “abc”). They are not shown in the list below and the submission cannot be approved — have the contractor check it (writing the numbers correctly) and resubmit.",
  "{0} нүдний нэмэлт нийт дүнг сөрөг болгоно (суурь утгаас их хасалт) тул батлах боломжгүй — доорх нүд(ийг) гүйцэтгэгчээр залруулуулж дахин илгээүүлнэ үү:": "{0} cell(s) would make the running total negative (more was subtracted than the base value), so this cannot be approved — have the contractor correct the cell(s) below and resubmit:",
  "Шийдвэр хадгалагдсан, гэхдээ анхаарах зүйл байна": "Decision saved, but needs attention",
  "Өөрчлөлтгүй дахин илгээх": "Resend unchanged",
  "Илгээлтээ татаж авах": "Withdraw my submission",
  "Инженерийн обьёмын {0} нүдийг батлах уу? Утгууд шууд үндсэн өгөгдөлд бичигдэж, гүйцэтгэлийн хувь дахин бодогдоно.": "Approve {0} engineer volume cell(s)? The values are written straight to the main data and progress percentages are recalculated.",
  "Утгууд үндсэн өгөгдөлд АЛЬ ХЭДИЙН бичигдсэн, гэхдээ илгээлтийг «Батлагдсан» болгож чадсангүй ({0}). Хуудсаа шинэчлээд «Обьём батлах»-ыг дахин дарна уу — ижил утга дахин бичигдэх тул аюулгүй. Давтан унавал админд мэдэгдэнэ үү.": "The values were ALREADY written to the main data, but the submission could not be marked “Approved” ({0}). Refresh the page and press “Approve volume” again — the same values are rewritten, so it is safe. If it keeps failing, notify an admin.",
  "Обьёмын илгээлтээ ({0} нүд) татаж авах уу? Батлагч үүнийг цаашид харахгүй; засаад дахин илгээж болно.": "Withdraw your volume submission ({0} cell(s))? The approver will no longer see it; you can edit and resubmit.",
  "Татаж авч чадсангүй.": "Could not withdraw it.",
  "Обьёмын илгээлтийг татаж авлаа.": "The volume submission was withdrawn.",
  "Буцаасан илгээлтийг ({0}) ӨӨРЧЛӨЛТГҮЙ, хэвээр нь дахин хяналтад илгээх үү? Хянагч өмнөх агуулгыг дахин хянана.": "Resend the sent-back submission ({0}) for review UNCHANGED, as is? The reviewer will review the previous content again.",
  "Өөрчлөлтгүй дахин илгээв ({0})": "Resent unchanged ({0})",
