  "Багц хоорондын ажлын хамаарал — нэг багцын ажил өөр багцуудын аль ажлаас хамаардгийг": "Work dependencies between packages — which works of other packages a package’s work depends on",
  "Нэг багцын ажил өөр багцуудын аль ажлаас хамаардгийг харуулна. Зөвхөн мэдээлэл — хуваарийн огноонд нөлөөлөхгүй.": "Shows which works of other packages each work depends on. Information only — it does not change schedule dates.",
