  "Хуудас зэрэг шинэчлэгдэж байна — дахин оролдоно уу": "The sheet is being updated at the same time — try again",
  "Серверийн хариу алдагдаж, хадгалагдсангүй — дахин оролдоно уу": "The server response was lost and nothing was saved — try again",
  "Архивлалтын төлөв шалгагдсангүй ({0}) — юу ч бичсэнгүй, дахин оролдоно уу.": "Could not check the archiving status ({0}) — nothing was written, try again.",
  "Уншигдаагүй хуудас ({0}) — дугуй хамаарлыг шалгах боломжгүй тул хадгалсангүй: {1}": "Sheets not loaded ({0}) — circular dependencies cannot be checked, so nothing was saved: {1}",
