  "ижил нэртэй мөр нэмэгдсэн/хасагдсан — аль нь болохыг тодорхойлж чадсангүй": "a row with the same name was added/removed — could not tell which one it is",
  "ажил олдсонгүй (устсан эсвэл нэр нь өөрчлөгдсөн)": "work not found (deleted or renamed)",
