  "Бөглөх хуудсууд уншигдсангүй": "The progress sheets could not be loaded",
  "«{0}» талбар бөглөх хуудсуудад хараахан нэмэгдээгүй — зөвхөн харах горим. Админ талбарыг нэмэнгүүт засвар өөрөө нээгдэнэ.": "The “{0}” field has not been added to the progress sheets yet — view-only mode. Editing turns on automatically once an admin adds the field.",
  "«{0}» талбаргүй хуудас ({1}) — тэдгээрийн ажилд хамаарал хадгалах боломжгүй (зөвхөн харах): {2}": "Sheets without the “{0}” field ({1}) — dependencies cannot be saved for their works (view only): {2}",
  "Уншигдаагүй хуудас ({0}) — дугуй хамаарлыг бүрэн шалгах боломжгүй тул хадгалахыг түр хаалаа: {1}": "Sheets not loaded ({0}) — circular dependencies cannot be fully checked, so saving is disabled for now: {1}",
  "Эвдэрсэн бичлэгтэй ажил ({0}) — тэдгээрийн хамаарлыг уншиж/засах боломжгүй, админд хандана уу: {1}": "Works with a corrupt record ({0}) — their dependencies cannot be read or edited, contact an admin: {1}",
  "Хуучин багц хоорондын холбоо — ажлыг нь сонгож шилжүүлнэ үү": "Old package-to-package links — pick the works to migrate them",
