  "Багцын хамаарал засах": "Edit package dependencies",
  "Багц хоорондын хамаарлын холбоо нэмэх, устгах эрх — аккаунтаар олгоно.": "Permission to add and remove links between packages — granted per account.",
  "«Багцын хамаарал» дээр багц хоорондын холбоо нэмэх, устгах. Багц нэмэх, хасах боломжгүй; батлагч байхгүй — хадгалсан холбоо шууд бүх хүнд харагдана. Эрхгүй хүн зөвхөн харна.": "Add and remove links between packages in “Package dependencies”. Packages cannot be added or removed; there is no approver — saved links are immediately visible to everyone. Users without the permission can only view.",
  "Нэвтрэлт сэргэсэнгүй — холболтоо шалгах эсвэл дахин нэвтэрнэ үү.": "Sign-in could not be restored — check your connection or sign in again.",
  "Нэвтрэлтийн хугацаа дууссан": "Your sign-in has expired",
  "ArcGIS-ийн нэвтрэлтийн хугацаа дууссан тул өгөгдөл унших, хадгалах боломжгүй боллоо. Нээлттэй ажил тань энэ цонхны ард хэвээр байна.": "Your ArcGIS sign-in has expired, so data can no longer be read or saved. Your open work is still there behind this window.",
  "Дахин нэвтрэх": "Sign in again",
  "Түр хаах — хадгалаагүй ажлаа хуулж авах": "Close temporarily — copy my unsaved work",
  "Порталын шинэ хувилбар гарсан — хуудсыг дахин ачаална уу": "A new version of the portal is available — please reload the page",
  "Товшсон цэгийн асуулга амжилтгүй — сүлжээгээ шалгаад дахин товшино уу.": "The query for the clicked point failed — check your connection and click again.",
  "Хадгалаагүй засвар байна. Өгөгдлийг шинэчлэхэд засвар алдагдаж болзошгүй. Шинэчлэх үү?": "You have unsaved changes. Refreshing the data may discard them. Refresh anyway?",
  "Сүлжээний холболт тасарсан": "Network connection lost",
  "Өгөгдлийг сүүлд бүтнээр шинэчилсэн цаг": "Time of the last full data refresh",
  "Бүх өгөгдлийг дахин татах": "Reload all data",
  "⚠️ «{0}» нэртэй ArcGIS хэрэглэгч олдсонгүй (эсвэл харагдахгүй). Нэрээ дахин шалгана уу — буруу бол хадгалахаас өмнө ноорогоос хасна уу.": "⚠️ No ArcGIS user named “{0}” was found (or it is not visible). Double-check the name — if it is wrong, remove it from the draft before saving.",
  "⚠️ «{0}» нь манай байгууллагын ArcGIS бүртгэл биш — нэвтрэхэд татгалзагдана. Нэрээ дахин шалгана уу.": "⚠️ “{0}” is not an ArcGIS account in our organization — sign-in will be refused. Double-check the name.",
  "… ба өөр {0} цоорхой": "… and {0} more gaps",
  "⚠️ Энэ өөрчлөлтөөр ажил ГАЦААХ шинэ цоорхой үүснэ:": "⚠️ This change creates new gaps that will BLOCK work:",
  "Тоо оруулна уу — 12.5 гэж бичнэ үү": "Enter a number — e.g. 12.5",
  "Сөрөг тоо байж болохгүй": "Negative numbers are not allowed",
  "«{0}» талбарын тоо буруу — 12.5 гэж бичнэ үү": "Invalid number in field “{0}” — write it like 12.5",
  "{0} энэ багцын обьёмыг түрүүлж илгээсэн байна — таны илгээлт цуцлагдлаа. Эхлээд шийдвэрлүүлнэ үү.": "{0} submitted this package's volumes first — your submission was cancelled. Have theirs decided first.",
  "«{0}» мөрийн эрхийн өгөгдөл хэт урт ({1} тэмдэгт, дээд тал нь {2}) тул хадгалагдсангүй — багцын жагсаалтыг цөөлөх эсвэл «Бүх багц» болгоно уу.": "The permission data for row “{0}” is too long ({1} characters, max {2}) and was not saved — reduce the package list or switch to “All packages”.",
  "Огнооны он буруу байна (2000–2100).": "The year of the date is invalid (2000–2100).",
  "Сарын хувь 0–100 хооронд байх ёстой: {0}.": "Monthly percent must be between 0 and 100: {0}.",
  "Сарын хувийн нийлбэр 100% биш ажил: {0}. Ийм хэвээр хадгалах уу?": "Works whose monthly percents do not sum to 100%: {0}. Save anyway?",
  "Серверээс хариу ирсэнгүй — объект нэмэгдсэн эсэх ТОДОРХОЙГҮЙ. Дахин нэмэхээс өмнө газрын зургийг шинэчилж, объект үүссэн эсэхийг шалгана уу.": "No response from the server — it is UNKNOWN whether the feature was added. Refresh the map and check whether it exists before adding again.",
  "Шалгасан — үүсээгүй, дахин нэмэх": "Checked — not created, add again",
  "«{0}» — «{1}»: таслал мянгатын уу, аравтын уу тодорхойгүй. Таслалгүй (1250) эсвэл цэгтэй (1.25) бичнэ үү.": "“{0}” — “{1}”: unclear whether the comma is a thousands or a decimal separator. Write it without a comma (1250) or with a dot (1.25).",
  "«{0}» — хувь 0–100 хооронд байх ёстой: {1}": "“{0}” — percent must be between 0 and 100: {1}",
  "Энэ илгээлт өмнөх шатны зөвшөөрлөөс ХОЙШ ({0}) дахин шинэчлэгдсэн — өмнөх зөвшөөрөл энэ агуулгыг ХАРААГҮЙ. Өөрчлөгдсөн нүд бүрийг шинээр хянана уу.": "This submission was updated again AFTER the previous stage approved it ({0}) — the earlier approval did NOT see this content. Review every changed cell afresh.",
  "Гэрээний хугацаанаас ({0} — {1}) гарч байна": "Outside the contract period ({0} — {1})",
  "{0}: сөрөг эсвэл буруу утга — нүд хоосон үлдлээ. 0 эсвэл эерэг тоо бичнэ үү.": "{0}: negative or invalid value — the cell was left empty. Enter 0 or a positive number.",
  "«Тавих» хаалттай": "“Apply” is disabled",
  "{0} · {1}:\nнийт {2} болж 100%-иас ХЭТЭРЧ байна.\nҮргэлжлүүлэх үү?": "{0} · {1}:\nthe total becomes {2}, EXCEEDING 100%.\nContinue?",
  "{0} · {1}: {2}% гэж бичигдлээ. {3}% гэх гэсэн бол засна уу — хувийг 0–100-аар бичнэ.": "{0} · {1}: recorded as {2}%. If you meant {3}%, correct it — enter percent as 0–100.",
  "ноорог хэт том": "draft too large",
  "өөр хүн зэрэг бичиж байна": "someone else is writing at the same time",
  "«Дуусах» ({0}) нь «Эхлэх»-ээс ({1}) ӨМНӨ байна — төлөвлөгөөт хувь бодогдохгүй": "“End” ({0}) is BEFORE “Start” ({1}) — planned % cannot be computed",
