  "«Шинэчлэгдсэн огноо» ({0}) нь ИРЭЭДҮЙН өдөр байна — төлөвлөгөөт хувь тэр өдрөөр бодогдоно. Санаатай биш бол засна уу.": "“Updated date” ({0}) is in the FUTURE — planned % will be computed for that day. Fix it if unintended.",
