  "Обьём ба Нэгж өртөг нь сөрөг биш тоо байх ёстой — «1,250» мэтийг тодорхойгүй тул 1250 эсвэл 1.25 гэж бичнэ үү.": "Volume and unit cost must be non-negative numbers — values like “1,250” are ambiguous, so write 1250 or 1.25.",
