  "Орон сууцны гүйцэтгэл төлөвлөгөөнөөс (pp)": "Housing progress vs plan (pp)",
  "Салбар багцууд «Багцын хамаарал» хэсэгт бүртгэсэн холбоосоос; «—» — холбоо бүртгээгүй. Код дээр дарж дэлгэрэнгүйг нээнэ.": "Sub-packages come from links registered in “Package dependencies”; “—” means no link registered. Click a code to open details.",
