  "төлөвлөсөн": "planned",
  "Огноо нь «Хуваарь» хэсгийн «Улсын комисс» мөрөөс. Салбар багцууд «Багцын хамаарал» хэсэгт бүртгэсэн холбоосоос; «—» — холбоо бүртгээгүй.": "Date comes from the “State commission” row in “Schedule”. Sub-packages come from links registered in “Package dependencies”; “—” means no link registered.",
  "«Багцын хамаарал» хэсэгт бүртгэсэн холбоосоос.": "From links registered in “Package dependencies”.",
  "Барилгын блок уншигдсангүй": "Building blocks failed to load",
  "Төлөвийг сонгоно уу — одоогийн утга танигдаагүй.": "Select a status — the current value is not recognised.",
  "Одоогийн төлөв танигдаагүй — сонгоно уу": "Current status not recognised — please select one",
  "Серверээс хариу ирсэнгүй — зөвшөөрөл нэмэгдсэн эсэх ТОДОРХОЙГҮЙ. Дахин хадгалахаас өмнө хуудсыг дахин ачаалж, зөвшөөрөл үүссэн эсэхийг шалгана уу.": "No response from the server — it is UNKNOWN whether the permit was added. Before saving again, reload the page and check whether the permit was created.",
  "«{0}» хүснэгт олдсонгүй эсвэл эзэн нь танигдсангүй — багцын хамаарлыг уншиж чадсангүй": "Table \"{0}\" not found or its owner not recognised — could not read package dependencies",
  "Энэ илгээлтийн обьёмыг батлагч ({0}) үндсэн өгөгдөлд ХЭСЭГЧЛЭН бичсэн — буцаах боломжгүй. «Обьём батлах»-ыг дахин дарж бичилтийг гүйцээнэ үү.": "The approver ({0}) has PARTIALLY written this submission's volumes to the main data — it cannot be returned. Click “Approve volume” again to complete the write.",
  "Батлагч ({0}) энэ илгээлтийн обьёмыг үндсэн өгөгдөлд ХЭСЭГЧЛЭН бичсэн — татах боломжгүй. Батлагч батлалтыг гүйцээнэ.": "The approver ({0}) has PARTIALLY written this submission's volumes to the main data — it cannot be withdrawn. The approver will complete the approval.",
  "Хагас бичилтийн хамгаалалтын тэмдэг хадгалагдсангүй ({0}) — үндсэн өгөгдөлд юу ч бичигдсэнгүй; дахин оролдоно уу.": "The partial-write protection mark could not be saved ({0}) — nothing was written to the main data; please try again.",
  "ArcGIS алдаа: «{0}» бүсийн {1} эх сурвалж хариу өгсөнгүй — өгөгдөл байхгүй гэсэн үг БИШ. Түр хүлээгээд дахин оролдоно уу.": "ArcGIS error: {1} source(s) for zone “{0}” did not respond — this does NOT mean there is no data. Please wait a moment and try again.",
  "⚠️ Хариу тасарсан (хэт урт болсон) — асуултаа хувааж эсвэл товчлон асууна уу.": "⚠️ The reply was cut off (too long) — split your question or ask more briefly.",
