  "Тодорхойгүй алдаа": "Unknown error",
  "{0} энэ багцад нэмэлт ажлыг түрүүлж илгээсэн байна — таны илгээлт цуцлагдлаа. Эхлээд шийдвэрлүүлнэ үү.": "{0} already submitted additional work for this package first — your submission was cancelled. Get that one decided first.",
  "Хүрээ нь хуваарилалтаас — танд энэ багц хуваарилагдаагүй. Панелийн «super» үүрэг зөвхөн харагдацыг нээнэ; батлахын тулд «Нэмэлт ажлын эрх» хэсэгт багц хуваарилна уу.": "Scope comes from assignments — this package is not assigned to you. The panel “super” role only opens views; to approve, assign packages in “Additional work permissions”.",
  "Уялдааны бичиглэл танигдсангүй: {0} — жишээ нь «18FS3,22SS-5». Уялдаа өөрчлөгдсөнгүй.": "Dependency notation not recognised: {0} — e.g. “18FS3,22SS-5”. Dependencies were not changed.",
