  "Дамжуулсан хэрэглэгч нэвтэрсэн хэрэглэгчтэй таарахгүй — шийдвэр бүртгэгдэхгүй.": "The passed user does not match the signed-in user — decision not recorded.",
  "Өмнөх шатыг та өөрөө зөвшөөрсөн — дараалсан хоёр шатыг нэг хүн шийдвэрлэх боломжгүй.": "You approved the previous stage yourself — one person cannot decide two consecutive stages.",
  "Архивт аль хэдийн бичигдсэн — дахин Батлах дарна уу, буцааж болохгүй": "Already written to the archive — press Approve again; it cannot be returned",
  "Таныг батлах хооронд {0} энэ ажлыг буцаасан байсан — архив аль хэдийн бичигдсэн тул буцаалт дарагдаж, ажил «Шилжүүлсэн» боллоо.": "While you were approving, {0} returned this work — the archive was already written, so the return was overridden and the work is now “Transferred”.",
