  "Энэ илгээлтийн өмнөх нэмэлт архивт бичигдсэн боловч илгээлт хаагдаагүй хэвээр — дахин батлавал нэмэлт ДАВХАР орно. Архивт юу ч бичсэнгүй; админаар илгээлтийн мөрийг шалгуулна уу.": "This submission's previous increments were archived but the submission is still open — approving again would add them TWICE. Nothing was archived; have an admin check the submission row.",
