  "Бодит огноо · нөөц түр түгжээтэй — «{0}» табын хүлээгдэж буй илгээлт шалгагдаагүй байна.": "Actual dates · resources temporarily locked — the pending submission on the “{0}” tab has not been checked yet.",
  "Бодит огноо · нөөц түгжээтэй — «{0}» табын хүлээгдэж буй илгээлт энэ мөрийн бодит огноо/нөөцийг агуулж байна. Шийдвэрлэгдсэний дараа засна.": "Actual dates · resources locked — the pending submission on the “{0}” tab contains this row's actual dates/resources. Edit after it is decided.",
  "Үргэлжлэх хоног {0}-аас их байж болохгүй — тавигдсангүй.": "Duration cannot exceed {0} days — not applied.",
  "Бичих зуур хуудасны жааз солигдсон (өөр батлалт/нийтлэл) — огноо хуучин жаазад бичигдсэн байж болзошгүй. Илгээлт «Хүлээгдэж буй» хэвээр (буцаах боломжгүй); хуудсаа шинэчлээд «Батлах»-ыг дахин дарна уу.": "The sheet frame changed during the write (another approval/publish) — dates may have been written to the old frame. The submission stays “Pending” (cannot be returned); refresh the page and press “Approve” again.",
  "Бичсэний дараах жаазын шалгалт унав — илгээлт «Хүлээгдэж буй» хэвээр (буцаах боломжгүй); хуудсаа шинэчлээд «Батлах»-ыг дахин дарна уу.": "The post-write frame check failed — the submission stays “Pending” (cannot be returned); refresh the page and press “Approve” again.",
  "{0} мөрийн ноорог одоогийн хуудаснаас олдохгүй (өнчин) — хадгалагдахгүй.": "Drafts of {0} rows were not found on the current sheet (orphaned) — they will not be saved.",
