  "ХАБЭА хуудасны «Бусад үзүүлэлт» (талбайн зааварчилгаа, сануулах хуудас, хариуцлага тооцох) ба «Хог хаягдал» картад шинэ бүртгэл нэмэх, үзлэгийн тайланг (PDF, Excel) татах. Батлагч байхгүй — хадгалсан бүртгэл шууд тоонд орно. Эрхгүй хүн карт энгийн харна, «Үзлэгийн тайлан татах» товч харагдахгүй.": "Add new records to the “Other indicators” (site briefings, warning notices, disciplinary actions) and “Waste” cards on the HSE page, and download inspection reports (PDF, Excel). No approver — saved records count immediately. Users without this permission see the cards as usual and do not see the “Download inspection report” button.",
