  "Эхлээд «Урьдчилан харах» дарж саналыг хуанли дээр шалгаад, өөрчлөгдсөн мөр бүрийг ногоон болгоно.": "First click “Preview” to check the proposal on the calendar and mark every changed row green.",
  "Бичсэн тайлбар батлахад хадгалагдахгүй. Үргэлжлүүлэх үү?": "The text you typed is not saved when approving. Continue?",
  "(Батлагч хуваарийг хуанли дээр нээлгүй буцаасан — өөрчлөгдсөн бүх мөрийг шалгана уу.)": "(The approver sent it back without opening the calendar — please check all changed rows.)",
  "Танд «{0}» шатанд зөвхөн ХАРАХ эрх байна — батлах/буцаах товч гарахгүй. Шийдвэр гаргах бол админаар «Гүйцэтгэлийн урсгал» хэсэгт энэ шатанд (зөвхөн харах тэмдэггүй) томилуулна уу.": "You have VIEW-ONLY access at the “{0}” stage — the approve/return buttons will not appear. To make decisions, ask an admin to assign you to this stage (without the view-only flag) in “Performance flow”.",
  "Нэвтэрсэн хэрэглэгчийн нэрийг порталаас баталгаажуулж чадсангүй — шийдвэр бүртгэгдсэнгүй, дахин оролдоно уу.": "Could not verify the signed-in user's name with the portal — the decision was not recorded; please try again.",
  "Хариу алдагдсан — шийдвэр хадгалагдсан эсэх тодорхойгүй. Жагсаалтыг дахин ачааллаа: төлөвийг шалгаад, өөрчлөгдөөгүй бол дахин оролдоно уу. ({0})": "Response lost — unknown whether the decision was saved. The list was reloaded: check the status and retry if it has not changed. ({0})",
  "Энэ гүйцэтгэлийг та өөрөө илгээсэн — өөрийн илгээлтийг хянах боломжгүй.": "You submitted this performance yourself — you cannot review your own submission.",
  "Эзлэх жингийн нийлбэр {0} — жин нь багц бүрийн төслийн нийт төсөвт эзлэх хувь бөгөөд орон сууцны бус (бөглөх хуудасгүй) багцууд энэ хүснэгтэд ороогүй тул нийлбэр 100%-иас бага; нийт гүйцэтгэлийг жингийн нийлбэрт харьцуулан тооцов. Багцын түвшинд төлөвлөгөөт хувь одоогоор байхгүй тул «—» тэмдгээр илэрхийлэв.": "Sum of weights {0} — each weight is the package's share of the whole project budget, and non-housing packages (without fill sheets) are not in this table, so the sum is below 100%; overall progress is computed relative to the weight sum. Package-level planned % is not available yet, shown as “—”.",
  "Танд зөвхөн ХАРАХ эрх олгогдсон — гүйцэтгэл илгээх боломжгүй.": "You have view-only access — you cannot submit performance.",
  "Танд «{0}» шатанд зөвхөн ХАРАХ эрх байна — гүйцэтгэл бөглөх, илгээх, засах боломжгүй. Илгээх бол админаар «Гүйцэтгэлийн урсгал» хэсэгт энэ шатанд (зөвхөн харах тэмдэггүй) томилуулна уу.": "You have VIEW-ONLY access at the “{0}” stage — you cannot fill, submit or edit performance. To submit, ask an admin to assign you to this stage (without the view-only flag) in “Performance flow”.",
  "Урсгалын томилгоог ачаалж байна…": "Loading flow assignments…",
  "Урсгалын томилгоо (багцын хуваарилалт) уншигдаагүй байна — сүлжээ эсвэл эрхийн хүснэгтийн уншилт унасан байж магадгүй.": "Flow assignments (package allocation) have not loaded — the network or the permissions table read may have failed.",
  "Хүснэгтэд он, огноо талбар байхгүй — өмнөх оны ижил дугаартай долоо хоногийн мөр нийлбэрт холилдож болзошгүй.": "The table has no year/date field — rows of the same week number from a previous year may be mixed into the total.",
