  "Барилга угсралтын ажлын ХО-оор жигнэсэн гүйцэтгэл {0} байна ({1} блокийн хэмжилтийг багцаар нь ХО дүнгийн жингээр нэгтгэсэн). Эдгээр багц төслийн төсвийн {2}-ийг эзэлдэг тул нийт гүйцэтгэлд шууд нөлөөлнө.": "Construction progress weighted by contract amount is {0} ({1} block measurements combined per package by contract-amount weight). These packages make up {2} of the project budget, so they directly drive overall progress.",
  "Сэлбэ 20 минутын хотын төслийн хэрэгжилт тайлан үүсгэх өдрийн байдлаар {0}-тай байна. Төслийн төсвийн {1}-ийг эзэлдэг барилга угсралтын ажил (ХО-оор жигнэсэн) {2}-ийн гүйцэтгэлтэй{3}. Газар чөлөөлөлтийн гүйцэтгэл нэгж талбарын төлвөөр{4} байгаа ч {5} нэгж талбар шийдвэрлэгдээгүй үлдсэн байна.": "As of the report date, implementation of the Selbe 20-minute city project stands at {0}. Construction work (weighted by contract amount), which makes up {1} of the project budget, is at {2} progress{3}. Land acquisition by parcel status is{4}, but {5} parcels remain unresolved.",
  "Төслийн нийт гүйцэтгэл (нэгтгэл гүйцэтгэл) уншигдсангүй. Төслийн төсвийн {0}-ийг эзэлдэг барилга угсралтын ажил (ХО-оор жигнэсэн) {1}-ийн гүйцэтгэлтэй{2}. Газар чөлөөлөлтийн гүйцэтгэл нэгж талбарын төлвөөр{3} байгаа ч {4} нэгж талбар шийдвэрлэгдээгүй үлдсэн байна.": "Overall project progress (consolidated) could not be read. Construction work (weighted by contract amount), which makes up {0} of the project budget, is at {1} progress{2}. Land acquisition by parcel status is{3}, but {4} parcels remain unresolved.",
