  "Хяналтын {0} блокийн нийт гүйцэтгэлийн энгийн дундаж {1} байна{2}{3}. 6.2-р хүснэгтийн үе шатын дундаж нь зөвхөн тайлагнасан {4} блокоор тооцогдоно.": "The simple average progress of the {0} monitored blocks is {1}{2}{3}. The stage averages in table 6.2 use only the {4} reporting blocks.",
