  "Урьдчилсан трасс: автозам, явган замын коридороор ижил төрлийн одоо байгаа сүлжээнд холбоно. Барилгын дундуур дайрахгүй; дундын шугамын уртыг нэг удаа тооцно. Энэ нь систем тус бүрийн трассын урт бөгөөд хос хоолой, кабелийн тоо хэмжээ биш. Хүчин чадал, диаметр, даралт, бохир усны хэвгий болон газар ашиглалтын эрхийг баталгаажуулаагүй.": "Preliminary routes follow road and pedestrian corridors to existing networks of the same utility type. Routes avoid buildings; shared trunks are counted once. Figures measure routes per utility system, not quantities of paired pipes or cables. Capacity, diameter, pressure, sewer gradients and land access rights have not been verified.",
