  "Барилга олон төрлийн холболт шаардсан ч нийт болон бүсийн тоонд нэг удаа орно. Нэмэгдэх урт нь эдгээр барилгад үйлчлэх дундын хэсгийг давхардуулаагүй бүтэн трасс; бүс доторх урт нь газрын зураг дээр хилээр тайрсан хэсэг юм.": "A building requiring multiple utility connections is counted once overall and within its zone. Additional length measures the complete routes serving these buildings, with shared sections counted once; within-zone length measures the portions clipped to zone boundaries on the map.",
