  "`compute`-ийн багцын задаргаа — тайлагнасан блокийн тоог хамт хэл.": "The package breakdown from `compute` — state the number of reported blocks too.",
  "Хамгийн хоцорсон блокууд аль нь вэ?": "Which blocks are furthest behind?",
  "`compute`-ийн хоцорсон блокийн жагсаалт (гүйцэтгэгч, сүүлийн мэдээний огноотой).": "The lagging-block list from `compute` (with contractor and last report date).",
  "Багц N-д юу байна? Дэлгэрэнгүй мэдээлэл?": "What is in Package N? Full detail?",
  "`zone_overview` — бүх эх сурвалжийг нэг дуудлагаар. Давхарга бүрийг тусад нь асуувал эргэлт хүрэхгүй.": "`zone_overview` — every source in one call. Querying layer by layer runs out of turns.",
  "Барилгын тоо, төлөв, давхар, зориулалт?": "Building count, status, floors, use?",
  "`et:24` дээр `stats` + `groupBy` (төлөв/зориулалтын талбараар). Мөр татаж өөрөө тоолохгүй.": "`stats` + `groupBy` on `et:24` (status/use field). Do not pull rows and count them yourself.",
  "Хүн ам, өрхийн тоо?": "Population and household count?",
  "`et:24`: хүн ам ба өрхийн талбарын нийлбэр. Хүчин чадлыг (сургууль, эмнэлэг) НЭМЭХГҮЙ.": "`et:24`: sum of the population and household fields. Do NOT add capacity (schools, clinics).",
