  "Багцын гүйцэтгэл — батлагдсан тоо?": "Package progress — the approved figure?",
  "`ds:pkg_progress` (батлагдсан нэгтгэл). Бөглөж буй хуудасны тоотой зөрвөл аль нь болохыг ил хэл.": "`ds:pkg_progress` (the approved rollup). If it differs from the live sheet, say which one you used.",
  "Хуваарь, ажлын явц, эхлэх/дуусах огноо?": "Schedule, task progress, start/end dates?",
  "`ds:task_sheet` — энэ нь НЭГ багцын төлөөлөл хуудас. Бүх багцын нэгдсэн дүнд `ds:pkg_progress` ашигла.": "`ds:task_sheet` — this is one representative package sheet. For an all-package total use `ds:pkg_progress`.",
  "ХАБЭА — ажилтан, техник, осол?": "HSE — workers, equipment, incidents?",
  "`ds:habea`: өдрийн сүүлийн тайлан. Огноогоор эрэмбэлж сүүлийн утгыг ав, огноог заавал дурд.": "`ds:habea`: the latest daily report. Order by date, take the last value, and always cite the date.",
  "Газар чөлөөлөлт хэдэн хувьтай вэ?": "What is the land-clearance progress?",
  "Мэдрэгчийн заалт (агаар, ус, дулаан)?": "Sensor readings (air, water, heat)?",
  "IoT эх сурвалжууд: хэмжсэн хугацаагаар эрэмбэлж сүүлийн заалт; хоосон утгыг шүүж хас, огноог дурд.": "IoT sources: order by measurement time for the latest reading; filter out empty values and cite the date.",
