  "Материалын нөөцийн хүснэгтэд «mir_id» талбар алга — админ String (урт ≥ {0}) эсвэл GUID төрлөөр нэмнэ үү.": "The material inventory table has no “mir_id” field — an admin must add it as String (length ≥ {0}) or GUID.",
  "«mir_id» талбарын төрөл {0} — String (урт ≥ {1}) эсвэл GUID байх ёстой.": "The “mir_id” field is of type {0} — it must be String (length ≥ {1}) or GUID.",
  "«mir_id» талбарын урт {0} — GUID багтахгүй; String (урт ≥ {1}) эсвэл GUID байх ёстой.": "The “mir_id” field length is {0} — a GUID does not fit; it must be String (length ≥ {1}) or GUID.",
