  "Хадгалаагүй ажил байна. «Гүйцэтгэл бөглөх»-ийн ноорог энэ хөтчид хадгалагдсан тул нэвтэрмэгц сэргэнэ; бусад хуудасны хадгалаагүй өөрчлөлт алдагдана — эхлээд «Түр хаах» дарж хуулж авна уу. Үргэлжлүүлэх бол «Дахин нэвтрэх»-ийг дахин дарна уу.": "You have unsaved work. Your “Enter progress” draft is saved in this browser and will be restored once you sign in; unsaved changes on other pages will be lost — press “Close temporarily” first and copy them. To continue, press “Sign in again” once more.",
  "Дахин нэвтрэхэд хуудас дахин ачаалагдана. «Гүйцэтгэл бөглөх»-ийн ноорог энэ хөтчид хадгалагдсан тул нэвтэрмэгц сэргэнэ. Бусад хуудасны ХАДГАЛААГҮЙ өөрчлөлт алга болно — хэрэгтэй бол эхлээд энэ цонхыг түр хааж хуулж авна уу.": "Signing in again reloads the page. Your “Enter progress” draft is saved in this browser and will be restored once you sign in. UNSAVED changes on other pages will be lost — if needed, close this window temporarily and copy them first.",
  "Хадгалалгүй гарах": "Leave without saving",
  "Хадгалалгүй шилжих": "Switch without saving",
  "Бүгдийг илгээх": "Send all",
  "Зөвхөн энэ сешнийх": "This session only",
  "Энэ хөтчид өмнөх сешнээс үлдсэн, ArcGIS-т хадгалагдаагүй эрхийн өөрчлөлт байна: {0}. Эдгээрийг ТАНЫ эрхээр ArcGIS руу бичих үү? (Хаалтанд — бичсэн хүн; энэ хөтчийн хадгалалтаас уншсан тул баталгаагүй.) «Зөвхөн энэ сешнийх» дарвал зөвхөн энэ сешний өөрчлөлтийг илгээнэ.": "This browser has permission changes left from an earlier session that were not saved to ArcGIS: {0}. Write them to ArcGIS with YOUR rights? (In brackets — who made them; read from this browser's storage, so not verified.) Press “This session only” to send only this session's changes.",
  "{0} өөрчлөлт дахин хүрсэнгүй — холболтоо шалгаад «Дахин илгээх» дарна уу.": "{0} changes still did not reach the server — check your connection and press “Resend”.",
