  "Үргэлжлүүлэх": "Continue",
  "Устгаж хадгалах": "Delete and save",
  "Арилгаад нэмэх": "Remove and add",
  "ArcGIS-т хадгалагдсангүй — зөвхөн энэ хөтчид": "Not saved to ArcGIS — only in this browser",
  "«{0}» ноорогт нэмэгдлээ. «Хадгалах» дарсны дараа багц болон засах эрхийн хуудсуудад сонгогдоно.": "“{0}” was added to the draft. After you press “Save” it can be picked on the package and edit-rights pages.",
  "Картын «Төрлөөр тохируулах» ба хажуугийн цэсний эрхийн хуудсууд ШУУД хадгалагдана. Шинэ аккаунтад «Хадгалах» дарсны дараа л багц, засах эрх олгоно.": "The card's “Apply type” and the rights pages in the side menu save IMMEDIATELY. A new account can be given packages and edit rights only after you press “Save”.",
  "⚠️ Эрхийн хүснэгт уншигдсангүй — нэмэх/устгах/сэргээх засвар хаалттай, дахин ачаална уу. Засах эрхээр нээгдсэн харагдацын тэмдэг энэ хөтчийн түр санах ойноос харагдаж байна.": "⚠️ The permissions table could not be read — adding, deleting and restoring are locked; please reload. Views opened by edit rights are shown from this browser's temporary storage.",
  "⚠️ ArcGIS хүснэгтээс уншиж чадсангүй — доорх жагсаалт энэ хөтчийн түр санах ойноос. Өөрчлөлт түр энэ хөтчид хадгалагдаж, холболт сэргэхэд автоматаар илгээгдэнэ.": "⚠️ Could not read the ArcGIS table — the list below is from this browser's temporary storage. Changes are kept in this browser for now and sent automatically when the connection returns.",
  "🔴 Эрхийн хүснэгтийн эзэн «{0}» нь итгэмжлэгдсэн эзний жагсаалтад алга тул БҮХ хэрэглэгчийн эрх, хуваарилалт уншигдахгүй байна. Засвар: порталд хүснэгтийн эзнийг одоогийн админд шилжүүлэх (Change owner), эсвэл хөгжүүлэгчид мэдэгдэж энэ нэрийг итгэмжлэгдсэн эзний жагсаалтад нэмүүлнэ.": "🔴 The permissions table owner “{0}” is not on the trusted owner list, so NO user's rights or assignments can be read. Fix: in the portal, transfer the table's ownership to the current admin (Change owner), or ask a developer to add this name to the trusted owner list.",
  "🔴 Эрхийн хүснэгт (Selbe_Permissions) НИЙТЭД нээлттэй байна — нэвтрээгүй хэн ч эрх засаж чадна. Порталд хүснэгтийн хуваалцах тохиргоог (Share) «Organization» болгоно уу.": "🔴 The permissions table (Selbe_Permissions) is PUBLIC — anyone, even signed out, can edit rights. In the portal, set the table's sharing (Share) to “Organization”.",
  "Сонголт арилгах": "Clear selection",
  "«{0}» хайлтад тохирох аккаунт алга — хайлтыг цэвэрлэх (✕) эсвэл хажуугийн талбараас шинэ аккаунт нэмнэ үү.": "No account matches “{0}” — clear the search (✕) or add a new account in the field beside it.",
  "Өөрчлөлт ArcGIS дээрх хуваалцсан хүснэгтэд хадгалагдаж, бүх хэрэглэгчид (өөр төхөөрөмжөөс нэвтэрсэн ч) үйлчилнэ. ArcGIS-т холбогдоогүй үед түр зуур энэ хөтчид хадгалагдана.": "Changes are saved to the shared table on ArcGIS and apply to all users (even on other devices). While ArcGIS is unreachable they are kept in this browser for now.",
  "Дахин илгээх ({0})": "Resend ({0})",
