  "ArcGIS хүснэгтэд бичиж чадсангүй — өөрчлөлт бусад төхөөрөмжид үйлчлэхгүй. «Дахин илгээх» товчоор дахин илгээнэ.": "Could not write to the ArcGIS table — the change will not apply on other devices. Press “Resend” to resend it.",
  "«{0}»-д Админ (super) эрх олгох уу? Тэр БҮХ хуудас, БҮХ засах эрхтэй болно — санхүүгийн мөр устгах, зөвшөөрөл, бусад хэрэглэгчийн эрх удирдах, системийг түр хаах зэрэг. Зөвхөн итгэмжлэгдсэн админд олгоно уу.": "Grant Admin (super) rights to “{0}”? They will get ALL pages and ALL edit rights — including deleting finance rows, permits, managing other users' rights and temporarily closing the system. Grant this only to a trusted admin.",
