  "⚠️ ArcGIS-т бичигдсэнгүй — хуваарилалт түр зөвхөн энэ хөтчид. Холболтоо шалгаад дахин оролдоно уу.": "⚠️ Not written to ArcGIS — the assignment is only in this browser for now. Check your connection and try again.",
