  "Хуучин багц хоорондын холбоо уншигдсангүй": "Could not load the old package-to-package links",
  "Ажлын холбоо хадгалагдмагц тухайн хуучин холбоо автоматаар устна.": "Once a task link is saved, the corresponding old link is removed automatically.",
  "Хайлт эсвэл шүүлтэд тохирох ажил алга — хайлтаа өөрчилнө үү.": "No tasks match the search or filter — change your search.",
