  "Засвар хаях": "Discard edits",
  "Хадгалагдлаа — {0} мөр": "Saved — {0} rows",
  "Засах боломжгүй: энэ хүснэгтэд засвар хаалттай байна — админд мэдэгдэнэ үү.": "Can't edit: editing is disabled for this table — please notify an admin.",
  "Хадгалсан өгөгдлийг дахин уншиж байна…": "Reloading the saved data…",
  "Энэ хүснэгтэд засвар хаалттай": "Editing is disabled for this table",
  "Засах горим: тодруулсан нүд л засагдана (Excel-ийн томьёогүй нүд). Засварласан нүд НОГООН, томьёогоор дахин бодогдсон нүд ЦЭНХЭР. «Хадгалах» дарах хүртэл хадгалагдахгүй.": "Edit mode: only highlighted cells can be edited (cells without an Excel formula). Edited cells are GREEN, cells recalculated by formula are BLUE. Nothing is saved until you press “Save”.",
  "Шинэ өгөгдөл бий — хадгалсны/болисны дараа шинэчлэгдэнэ. Хадгалахад хүснэгтийг шинээр уншиж зөрчлийг шалгана.": "New data is available — it will refresh after you save or cancel. Saving re-reads the table and checks for conflicts.",
  "Өгөгдлийг дахин уншиж чадсангүй — засвар тань хэвээр байна; хадгалахад хүснэгтийг шинээр уншиж шалгана.": "Could not reload the data — your edits are kept; saving re-reads the table and checks it.",
  "Хаяж хаах": "Discard and close",
  "Хуулах": "Copy",
  "{0} блокийн огноо ба сарын задаргаа арилгав.": "Cleared dates and monthly breakdown for {0} blocks.",
  "Сарын хүснэгтэд хүн хүч/машин механизмын талбар алга — сарын нөөц хадгалагдахгүй. Админд мэдэгдэнэ үү.": "The monthly table has no labour/machinery field — monthly resources won't be saved. Please notify an admin.",
  "Илгээгээгүй шинэ мөрийг хасах — «↶ Буцаах»-аар сэргээнэ": "Remove the unsubmitted new row — restore it with “↶ Undo”",
