  "Баримт бичгийн сан — PDF оруулах": "Document library — upload PDFs",
  "Баримт бичгийн сан — бүлэг үүсгэх": "Document library — create groups",
  "Цэсний «Баримт бичгийн сан» цонхонд байгаа бүлэгт PDF оруулах, өөрийн оруулсан PDF-ийг устгах, өөр бүлэгт шилжүүлэх. PDF нь Enterprise геопорталд хадгалагдаж байгууллагад хуваалцагдана. Бүлэг үүсгэх нь тусдаа эрх. Харах нь нэвтэрсэн бүх хэрэглэгчид нээлттэй.": "In the menu’s “Document library” window: upload PDFs into existing groups, delete your own PDFs and move them to another group. PDFs are stored in the Enterprise geoportal and shared with the organization. Creating groups is a separate permission. Viewing is open to all signed-in users.",
  "Цэсний «Баримт бичгийн сан» цонхонд бүлэг нэмэх, нэр солих, хоосон бүлгийг устгах. PDF оруулах нь тусдаа «Баримт оруулах» эрх.": "In the menu’s “Document library” window: add groups, rename them and delete empty ones. Uploading PDFs is the separate “Upload documents” permission.",
