  "Хувь 0–100; «—» = мэдээлэлгүй (0 биш). Гүйцэтгэгчийн төлөвлөгөө: блок → Хуваарь, бусад → огнооны хооронд жигд. Биелэлт = гүйцэтгэл ÷ төлөвлөгөө.": "Percent 0–100; \"—\" = no data (not 0). Contractor plan: blocks → Schedule, others → linear between dates. Achievement = actual ÷ plan.",
  "6 түвшний хуваарь": "6-level schedule",
  "Төслийн төлөвлөгөөг мастер хуваариас өдөр тутмын төлөвлөгөө хүртэл 6 түвшинд задална. Тоо нь Excel-ийн төлөвлөгөө, Хуваарь ба бөглөх хуудаснаас автоматаар бодогдоно.": "Breaks the project plan into 6 levels, from the master schedule down to the daily plan. Figures are computed automatically from the Excel plan, the Schedule and the fill sheets.",
  "Төслийн төлөвлөгөө импортлогдоогүй байна": "The project plan has not been imported yet",
  "Excel-ийн «Төсөл төлөвлөгөө биелэлт» хуудсыг санхүүжилтийн хүснэгтэд импортлосны дараа 6 түвшний хуваарь энд харагдана.": "The 6-level schedule appears here once the Excel «Project plan / progress» sheet has been imported into the funding table.",
