  "Milestone": "Milestone",
  "Барилгын ажлын эхлэх огноо = гүйцэтгэгчийн бодит төлөвлөгөөт эхлэх (багцын хамгийн эрт блок). «Хоцорсон» = төлөвлөгөөт хувиас {0}-аас дээш пунктээр доогуур.": "Construction start = contractor's actual planned start (earliest block of the package). «Behind» = more than {0} points below the planned percentage.",
  "Бага → их (мөр доторх хамгийн их утгатай харьцуулсан)": "Low → high (relative to the row's largest value)",
  "мэдээлэлгүй (хуваарь алга)": "no data (no schedule)",
  "Хоосон нүд = тухайн хугацаанд ажилгүй": "Empty cell = no work in that period",
  "Нүд = тухайн сард төлөвлөсөн гүйцэтгэл (мөрийн нийт ажлын %). Блок — Хуваарийн сарын төлөвлөгөө; багцын нийт — блокуудын жигнэсэн нийлбэр; «Өсөх дүн» — хуримтлагдсан.": "Cell = progress planned for that month (% of the row's total work). Block — Schedule monthly plan; package total — weighted sum of blocks; «Cumulative» — running total.",
  "Блокийн мөр: L4-ийн сарын хувийг өдөрт тэнцүү хувааж 7 хоногоор (Да–Ня) нэгтгэсэн. Дэд бүлэг: блокийн нийт ажлын хэдэн хувь тухайн хугацаанд хийгдэхээр төлөвлөгдсөн (бөглөх хуудасны төлөвлөгөөт эхлэх/дуусах, шугаман).": "Block row: L4's monthly percentage split evenly per day and summed by week (Mon–Sun). Sub-group: share of the block's total work planned for that period (fill-sheet planned start/finish, linear).",
  "Блокийн мөр: L4-ийн сарын хувийг тухайн сарын өдрийн тоонд тэнцүү хуваасан. Дэд бүлэг: блокийн нийт ажлын хэдэн хувь тухайн өдөр хийгдэхээр төлөвлөгдсөн (бөглөх хуудасны төлөвлөгөөт эхлэх/дуусах, шугаман).": "Block row: L4's monthly percentage split evenly over the days of that month. Sub-group: share of the block's total work planned for that day (fill-sheet planned start/finish, linear).",
