  "Хуваарьт нэгж өртөгтэй сарын обьём АЛГА — шилжүүлбэл энэ гэрээний сарын мөнгө ХООСОН болж S-муруйд орохгүй": "The schedule has NO monthly volume with a unit cost — after switching, this contract's monthly money will be EMPTY and will not appear in the S-curve",
