  "ТЭЗҮ ба ажлын зураг төслийн навч мөрийн огноо, явцыг засах эрх — аккаунтаар олгоно.": "Right to edit dates and progress of feasibility study and detailed design leaf rows — granted per account.",
  "«ТЭЗҮ · Ажлын зураг төсөл» дээр навч мөрийн эхлэх, дуусах огноо ба явцын хувийг засах, багцад дэд шат нэмэх. Батлагч байхгүй. Эрхгүй хүн зөвхөн харна.": "In «Feasibility study · Detailed design», edit leaf row start and end dates and progress percent, add sub-stages to a package. No approver. Users without the right can only view.",
  "Гэрээний гараар оруулсан сарын мөрийг УСТГАЖ, сарын мөнгийг Хуваарийн сарын обьём × нэгж өртгөөр тооцоолно. Буцаах боломжгүй.": "DELETES the contract's manually entered monthly rows and computes monthly money as Schedule monthly volume × unit cost. Cannot be undone.",
