  "Анхааруулга: {0} дэд шатны жин 0% — бусад дэд шат 100%-ийг эзэлсэн тул тэдгээрийн явц эцэг мөрөнд нөлөөлөхгүй. Жинг Excel-ээр засна уу.": "Warning: {0} sub-stage(s) have 0% weight — the other sub-stages already take 100%, so their progress will not count toward the parent row. Correct the weights in Excel.",
  "Жин 0% — бусад дэд шат 100%-ийг эзэлсэн тул энэ дэд шатны явц эцэг мөрөнд нөлөөлөхгүй. Жинг Excel-ээр засна уу.": "Weight 0% — the other sub-stages already take 100%, so this sub-stage's progress will not count toward the parent row. Correct the weights in Excel.",
