  "Багцын гэрээ/төсвийн дүн (гэрээгүй бол төсвөөр):": "Package contract/budget value (budget where not contracted):",
  "Багц сонгоход баруунд гэрээ/төсөв, эх үүсвэр, төлбөр, доор санхүүгийн график гарна. Зураг дээрх барилга дарахад тухайн багц сонгогдоно.": "Selecting a package shows the contract/budget, funding sources and payments on the right, with the finance chart below. Clicking a building on the map selects its package.",
  "Олгосон хувиар": "By paid share",
  "Барилгын давхарга": "Building layer",
  "100%-иас их": "over 100%",
  "Эхний {0} нь — дугаараа нарийсгана уу": "First {0} shown — please narrow the number",
  "Хэсэг заагаагүй": "No section given",
  "⚠️ `overall` (блокийн энгийн дундаж) ба `byBagts.actual`-ийн ХУВААРЬ нь бөглөх хуудасны БҮХ блок: тайлан ирээгүй блок 0% — порталын бүх дэлгэцтэй нэг дүрэм. «Төслийн нийт гүйцэтгэл» гэж асуувал `project`-ийг хэл (Ерөнхий дашбоардын «Гүйцэтгэлийн хувь», Тайлан, удирдлагын тайлантай нэг тоо); `housing` нь ЗӨВХӨН орон сууцны биет гүйцэтгэл (Дашбоардын «Биет гүйцэтгэл (багцаар)»), `overall` нь «блокийн дундаж» — гурвыг ялгаж нэрлэ. ": "⚠️ The denominator of `overall` (simple block mean) and `byBagts.actual` is every block in the fill sheets: blocks without a report count as 0% — the same rule as every portal screen. For \"total project progress\" give `project` (same figure as the General dashboard \"Progress %\", the Report and the executive report); `housing` is housing physical progress ONLY (Dashboard \"Physical progress (by package)\"), `overall` is the \"block mean\" — name the three distinctly. ",
  "- Төслийн НИЙТ ГҮЙЦЭТГЭЛ → `compute` `building_progress`-ийн `project` (нэгтгэл — Ерөнхий дашбоард «Гүйцэтгэлийн хувь», Тайлан).": "- Project TOTAL PROGRESS → `project` from `compute` `building_progress` (consolidation — General dashboard \"Progress %\", Report).",
  "  `housing` = ЗӨВХӨН орон сууцны биет гүйцэтгэл (ХО-жинтэй), `overall` = блокийн энгийн дундаж. Гурвыг ялгаж НЭРЛЭ.": "  `housing` = housing physical progress ONLY (investment-weighted), `overall` = simple block mean. Name the three distinctly.",
  "`compute` → `project` (нэгтгэл — Ерөнхий дашбоардын «Гүйцэтгэлийн хувь», Тайлантай нэг тоо). Орон сууцны биет гүйцэтгэл бол `housing`, блокийн дундаж бол `overall` — ИЛ нэрлэ.": "`compute` → `project` (consolidation — same figure as the General dashboard \"Progress %\" and the Report). For housing physical progress use `housing`, for the block mean `overall` — name them explicitly.",
  "`building_progress` — бөглөх хуудсаар бодсон БОДИТ гүйцэтгэл: ТӨСЛИЙН НИЙТ гүйцэтгэл (`project` — нэгтгэл, Ерөнхий дашбоардын «Гүйцэтгэлийн хувь»), орон сууцны ХО-жинтэй хувь (`housing` — Дашбоардын «Биет гүйцэтгэл (багцаар)»), блокийн дундаж (`overall`), багц бүрийн ": "`building_progress` — ACTUAL progress computed from the fill sheets: TOTAL project progress (`project` — consolidation, General dashboard \"Progress %\"), housing investment-weighted % (`housing` — Dashboard \"Physical progress (by package)\"), simple block mean (`overall`), per-package ",
  "`land` — газар чөлөөлөлтийн нийт/чөлөөлсөн/үлдсэн нэгж талбар, хувь (ТООГООР) ба талбай — порталын «Газар чөлөөлөлт»-ийн ЯГ тэр тоо. Газар чөлөөлөлтийн хувийг асуувал ЭНИЙГ ашигла.": "`land` — land clearance total/cleared/remaining parcels, percentage (BY COUNT) and area — exactly the portal \"Land clearance\" figure. Use THIS when asked for the land clearance percentage.",
  "Чөлөөлөлтийн хувь = «{0}» төлөвтэй нэгж талбарын ТОО ÷ бүх нэгж талбарын тоо (талбайгаар БИШ) — порталын тоог `compute` `land`-аас ав, `SUM(area_m2)`-аар бүү бод. ": "Clearance % = number of parcels with status «{0}» ÷ number of all parcels (NOT by area) — take the portal figure from `compute` `land`; do not compute it with `SUM(area_m2)`. ",
  "`compute` → `land` (порталын ЯГ тэр тоо — хувь нь нэгж талбарын ТООГООР, талбай давхардалгүй). `land:left`-ийн талбайг өөрөө бүү нийлүүл.": "`compute` → `land` (exactly the portal figure — percentage BY PARCEL COUNT, area without duplicates). Do not sum `land:left` areas yourself.",
  "`land:left` давхаргад хандах эрх алга.": "No access to the `land:left` layer.",
  "`pct` = чөлөөлсөн нэгж талбар ÷ бүх нэгж талбар (ТООГООР, талбайгаар БИШ) — порталын «Газар чөлөөлөлт», Тайлантай нэг тоо. `areaM2` нь нэгж талбар бүрийн талбай (давхардалгүй) — `SUM(area_m2)`-аар бүү бод.": "`pct` = cleared parcels ÷ all parcels (BY COUNT, not by area) — same figure as the portal \"Land clearance\" and the Report. `areaM2` is the per-parcel area (deduplicated) — do not compute it with `SUM(area_m2)`.",
  "Орон сууцны барилгажилт {7} багцад хуваагдан хэрэгжиж байна. Нийт {0} блокт {1} өрхийн орон сууц төлөвлөгдсөн бөгөөд төсөвт өртөг {2} ₮ байна. Багц хоорондын гүйцэтгэл ойролцоо байна: хамгийн өндөр нь {3} ({4}), хамгийн бага нь {5} ({6}).": "Housing construction is delivered in {7} packages. In total {1} households are planned in {0} blocks with an estimated cost of {2} MNT. Progress is similar across packages: the highest is {3} ({4}), the lowest {5} ({6}).",
