  "1. Хот төлөвлөлт": "1. Urban planning",
  "Үзүүлэлт бүр норм хангавал 100 оноо, зөрчвөл 44-өөс дээшгүй оноо авна. Бүсийн хот төлөвлөлтийн оноо нь үзүүлэлтүүдийн жигнэсэн дундаж; өгөгдөлгүй үзүүлэлт жингээс хасагдана. Босго утга БНБД 30-01-24-өөс.": "Each indicator scores 100 when the norm is met and at most 44 when violated. A zone's urban planning score is the weighted average of indicators; indicators without data are dropped from the weights. Thresholds are from BNBD 30-01-24.",
  "Бүсийн үнэлгээний түвшин": "Zone rating levels",
